11	struct BatchAIAnalysisControls: View {
12	    @Environment(SavedTermsStore.self) private var savedTermsStore
13	    @State private var controller = BatchExplanationController.shared
14	    @State private var settings = AIModelSettings.shared
15	    @State private var preferences = AppPreferences.shared
16	    @State private var generatedAudio = GeneratedSpeechStore.shared
17	
18	    @State private var generateAudio = false
19	    @State private var audioScope: BatchAudioScope = .bothLanguages
20	    @State private var isPreparing = false
21	    @State private var pendingPlan: BatchRunPlan?
22	    @State private var preparationError: String?
23	    @State private var showingSavedAudioLibrary = false
24	
25	    private var totalSaved: Int { savedTermsStore.terms.count }
26	    private var providerAvailable: Bool { settings.isAnyProviderAvailable }
27	    private var miniMaxKeyAvailable: Bool {
28	        !settings.apiKey(for: .minimax)
29	            .trimmingCharacters(in: .whitespacesAndNewlines)
30	            .isEmpty
31	    }
