33	    var body: some View {
34	        let remaining = controller.remainingCount(from: savedTermsStore.terms)
35	        Group {
36	            overviewSection(remaining: remaining)
37	            parallelismSection
38	            outputSection
39	            actionSection(remaining: remaining)
40	        }
