42	            await generatedAudio.refresh()
43	        }
44	        .sheet(item: $pendingPlan) { plan in
45	            BatchAudioPreflightView(
46	                plan: plan,
47	                onStart: {
48	                    pendingPlan = nil
49	                    controller.start(plan: plan, concurrency: settings.batchConcurrency)
50	                },
51	                onCancel: { pendingPlan = nil }
