53	            .localizedSurface()
54	        }
55	        .sheet(isPresented: $showingSavedAudioLibrary) {
56	            GeneratedAudioLibraryView()
57	                .localizedSurface()
58	        }
59	        .alert("Batch Preparation Failed", isPresented: preparationErrorBinding) {
60	            Button("OK", role: .cancel) {}
61	        } message: {
62	            Text(preparationError ?? String(localized: "The batch plan could not be prepared.", bundle: .appLanguage))
63	        }
64	    }
