66	    private func overviewSection(remaining: Int) -> some View {
67	        Section {
68	            LabeledContent("Saved Words") {
69	                Text("\(totalSaved)").foregroundStyle(.secondary)
70	            }
71	            LabeledContent("Analyzed") {
72	                Text("\(max(0, totalSaved - remaining))").foregroundStyle(.secondary)
73	            }
74	            LabeledContent("Needs Analysis") {
75	                Text("\(remaining)")
76	                    .foregroundStyle(remaining > 0 ? .primary : .secondary)
77	                    .fontWeight(remaining > 0 ? .semibold : .regular)
