79	            LabeledContent("Saved AI Audio") {
80	                Text("\(generatedAudio.records.count)")
81	                    .foregroundStyle(.secondary)
82	            }
83	        } header: {
84	            Text("Batch AI Analysis & Audio")
85	        } footer: {
86	            Text("Analyze missing saved words and optionally prepare persistent MiniMax pronunciation audio. Existing analyses and matching audio are reused.")
87	        }
