90	    private var parallelismSection: some View {
91	        Section {
92	            Stepper(value: $settings.batchConcurrency, in: AIModelSettings.batchConcurrencyRange) {
93	                LabeledContent("Analyses in Parallel") {
94	                    Text("\(settings.batchConcurrency)")
95	                        .monospacedDigit()
96	                        .foregroundStyle(.secondary)
97	                }
98	            }
99	            .disabled(controller.isRunning)
100	        } header: {
101	            Text("Parallelism")
102	        } footer: {
103	            Text("This controls AI analysis only. MiniMax audio uses at most two workers and starts no more than one new request per second to reduce rate-limit errors.")
104	        }
105	    }
106	
107	    private var outputSection: some View {
108	        Section {
109	            Toggle("Generate MiniMax Audio", isOn: $generateAudio)
110	                .disabled(controller.isRunning)
111	
112	            if generateAudio {
113	                Picker("Audio Languages", selection: $audioScope) {
114	                    ForEach(BatchAudioScope.allCases) { scope in
115	                        Text(scope.displayName).tag(scope)
116	                    }
117	                }
118	                .disabled(controller.isRunning)
119	
120	                LabeledContent("Speech Model") {
121	                    Text(preferences.aiAudioModel)
122	                        .foregroundStyle(.secondary)
123	                        .lineLimit(1)
124	                }
125	                if audioScope == .bothLanguages || LocalizationManager.shared.learningIsChinese {
126	                    LabeledContent("Mandarin Voice") {
127	                        Text(preferences.aiAudioChineseVoice)
128	                            .foregroundStyle(.secondary)
129	                            .lineLimit(1)
130	                            .truncationMode(.middle)
131	                    }
132	                }
133	                if audioScope == .bothLanguages || !LocalizationManager.shared.learningIsChinese {
134	                    LabeledContent("English Voice") {
135	                        Text(preferences.aiAudioEnglishVoice)
136	                            .foregroundStyle(.secondary)
137	                            .lineLimit(1)
138	                            .truncationMode(.middle)
139	                    }
140	                }
141	
142	                if !miniMaxKeyAvailable {
143	                    Label("Add a MiniMax API key in AI Audio settings.", systemImage: "key.fill")
144	                        .font(.caption)
145	                        .foregroundStyle(.orange)
146	                }
147	            }
148	        } header: {
149	            Text("Output")
150	        } footer: {
151	            if generateAudio {
152	                Text("Before any new paid speech requests begin, a confirmation shows exact cache misses and characters. Spoken terms are sent to MiniMax; generated MP3s remain in the Saved Audio library for playback and export.")
153	            } else {
154	                Text("Audio generation is off. This run will only create missing AI analyses.")
155	            }
156	        }
157	    }
158	
159	    @ViewBuilder
160	    private func actionSection(remaining: Int) -> some View {
161	        Section {
162	            if controller.isRunning {
163	                progressContent
164	                Button(role: .destructive) {
165	                    controller.cancel()
166	                } label: {
167	                    Label("Cancel Batch", systemImage: "stop.circle")
168	                }
169	            } else {
170	                startButton(remaining: remaining)
171	                lastRunSummary
172	            }
173	        } footer: {
174	            actionFooter(remaining: remaining)
175	        }
176	    }
177	
178	    private var progressContent: some View {
179	        VStack(alignment: .leading, spacing: 14) {
180	            if controller.analysisTotal > 0 {
181	                progressLane(
182	                    title: "AI Analysis",
183	                    value: controller.analysisProgress,
184	                    processed: controller.analysisProcessed,
185	                    total: controller.analysisTotal
186	                )
187	            }
188	
189	            if controller.audioTotal > 0 {
190	                progressLane(
191	                    title: "MiniMax Audio",
192	                    value: controller.audioProgress,
193	                    processed: controller.audioProcessed,
194	                    total: controller.audioTotal
195	                )
196	            }
197	
198	            HStack(spacing: 12) {
199	                Label("\(controller.analysesGenerated + controller.audioGenerated)", systemImage: "checkmark.circle.fill")
200	                    .foregroundStyle(.green)
201	                    .accessibilityLabel("\(controller.analysesGenerated + controller.audioGenerated) newly completed")
202	                if controller.audioCached > 0 {
203	                    Label("\(controller.audioCached)", systemImage: "bolt.fill")
204	                        .foregroundStyle(.blue)
205	                        .accessibilityLabel("\(controller.audioCached) audio clips already saved")
206	                }
207	                let failures = controller.analysesFailed + controller.audioFailed
208	                if failures > 0 {
209	                    Label("\(failures)", systemImage: "exclamationmark.triangle.fill")
210	                        .foregroundStyle(.orange)
211	                        .accessibilityLabel("\(failures) failed")
212	                }
213	                Spacer()
214	            }
215	            .font(.caption)
216	
217	            if let word = controller.lastWord, !word.isEmpty {
218	                Text("Last: \(word)")
219	                    .font(.caption2)
220	                    .foregroundStyle(.tertiary)
221	                    .lineLimit(1)
222	            }
223	        }
224	        .padding(.vertical, 2)
225	        .accessibilityElement(children: .contain)
226	        .accessibilityLabel("Batch progress details")
227	    }
228	
229	    private func progressLane(
230	        title: LocalizedStringKey,
231	        value: Double,
232	        processed: Int,
233	        total: Int
234	    ) -> some View {
235	        VStack(alignment: .leading, spacing: 6) {
236	            HStack {
237	                Text(title)
238	                    .font(.subheadline.weight(.medium))
239	                Spacer()
240	                Text("\(processed) / \(total)")
241	                    .monospacedDigit()
242	                    .foregroundStyle(.secondary)
243	            }
244	            ProgressView(value: value)
245	                .accessibilityHidden(true)
246	        }
247	        .accessibilityElement(children: .combine)
248	        .accessibilityLabel(Text(title))
249	        .accessibilityValue("\(processed) of \(total) complete")
250	    }
251	
252	    private func startButton(remaining: Int) -> some View {
253	        Button {
254	            prepareAndStart()
255	        } label: {
256	            HStack(spacing: 8) {
257	                if isPreparing {
258	                    ProgressView()
259	                        .controlSize(.small)
260	                        .accessibilityLabel("Preparing batch")
261	                }
262	                Label(startTitle(remaining: remaining), systemImage: generateAudio ? "waveform.badge.plus" : "sparkles")
263	                    .multilineTextAlignment(.center)
264	            }
265	            .frame(maxWidth: .infinity, minHeight: 44)
266	        }
267	        .buttonStyle(.borderedProminent)
268	        .controlSize(.large)
269	        .disabled(!canStart(remaining: remaining))
270	    }
271	
272	    private func canStart(remaining: Int) -> Bool {
273	        guard !isPreparing, totalSaved > 0 else { return false }
274	        if remaining > 0, !providerAvailable { return false }
275	        if generateAudio, !miniMaxKeyAvailable { return false }
276	        return remaining > 0 || generateAudio
277	    }
278	
279	    private func startTitle(remaining: Int) -> LocalizedStringKey {
280	        if isPreparing { return "Preparing Batch…" }
281	        if generateAudio {
282	            return remaining > 0 ? "Review Analysis & Audio Batch" : "Review Audio Batch"
283	        }
284	        return remaining > 0 ? "Analyze \(remaining) Words" : "All Words Analyzed"
285	    }
286	
287	    private func prepareAndStart() {
288	        guard !isPreparing else { return }
289	        isPreparing = true
290	        preparationError = nil
291	        Task { @MainActor in
292	            defer { isPreparing = false }
293	            do {
294	                let plan = try await controller.preparePlan(
295	                    from: savedTermsStore.terms,
296	                    includeAudio: generateAudio,
297	                    audioScope: audioScope
298	                )
299	                if generateAudio {
300	                    pendingPlan = plan
301	                } else {
302	                    controller.start(plan: plan, concurrency: settings.batchConcurrency)
303	                }
304	            } catch {
305	                preparationError = error.localizedDescription
306	            }
307	        }
308	    }
309	
310	    @ViewBuilder
311	    private var lastRunSummary: some View {
312	        switch controller.status {
313	        case let .finished(summary):
314	            summaryContent(summary, outcome: .finished)
315	        case let .cancelled(summary):
316	            summaryContent(summary, outcome: .cancelled)
317	        case let .failed(summary):
318	            summaryContent(summary, outcome: .failed)
319	        default:
320	            EmptyView()
321	        }
322	    }
323	
324	    private enum SummaryOutcome {
325	        case finished
326	        case cancelled
327	        case failed
328	    }
329	
330	    @ViewBuilder
331	    private func summaryContent(
332	        _ summary: BatchRunSummary,
333	        outcome: SummaryOutcome
334	    ) -> some View {
335	        VStack(alignment: .leading, spacing: 10) {
336	            runSummary(summary, outcome: outcome)
337	            if summary.audioGenerated > 0 || summary.audioCached > 0 {
338	                Button {
339	                    showingSavedAudioLibrary = true
340	                } label: {
341	                    Label("Manage Saved Audio", systemImage: "music.note.list")
342	                }
343	            }
344	        }
345	    }
346	
347	    private func runSummary(
348	        _ summary: BatchRunSummary,
349	        outcome: SummaryOutcome
350	    ) -> some View {
351	        let failures = summary.analysesFailed + summary.audioFailed
352	        let unattempted = summary.analysesUnattempted + summary.audioUnattempted
353	        let title: LocalizedStringKey
354	        let symbol: String
355	        let iconColor: Color
356	        switch outcome {
357	        case .finished:
358	            title = "Batch Complete"
359	            symbol = failures > 0 ? "checkmark.circle.badge.questionmark" : "checkmark.circle.fill"
360	            iconColor = failures > 0 ? .orange : .green
361	        case .cancelled:
362	            title = "Batch Cancelled"
363	            symbol = "stop.circle"
364	            iconColor = .secondary
365	        case .failed:
366	            title = "Batch Stopped"
367	            symbol = "exclamationmark.octagon.fill"
368	            iconColor = .red
369	        }
370	        return Label {
371	            VStack(alignment: .leading, spacing: 3) {
372	                Text(title)
373	                    .fontWeight(.medium)
374	                Text("Analyses \(summary.analysesGenerated) · Audio \(summary.audioGenerated) new, \(summary.audioCached) saved · Failed \(failures) · Not attempted \(unattempted)")
375	                    .font(.caption)
376	                    .foregroundStyle(.secondary)
377	            }
378	        } icon: {
379	            Image(systemName: symbol)
380	                .foregroundStyle(iconColor)
381	        }
382	    }
383	
384	    @ViewBuilder
385	    private func actionFooter(remaining: Int) -> some View {
386	        if remaining > 0, !providerAvailable {
387	            Text("No AI provider is available. Configure one in Settings → AI to analyze words.")
388	                .foregroundStyle(.orange)
389	        } else if generateAudio, !miniMaxKeyAvailable {
390	            Text("A MiniMax API key is required for batch audio. Add it in AI Audio settings.")
391	                .foregroundStyle(.orange)
392	        } else if controller.isRunning {
393	            Text("You may leave this screen while the app remains active. Completed analyses and audio files are saved immediately; cancelling keeps finished work.")
394	        } else if let error = controller.lastErrorMessage {
395	            Text("Last error: \(error)")
396	                .foregroundStyle(.secondary)
397	        } else {
398	            Text("Analysis uses \(settings.effectiveProvider.displayName). MiniMax audio is opt-in and cache-first.")
399	        }
400	    }
401	
402	    private var preparationErrorBinding: Binding<Bool> {
403	        Binding(
404	            get: { preparationError != nil },
405	            set: { if !$0 { preparationError = nil } }
406	        )
407	    }
408	}
