410	private struct BatchAudioPreflightView: View {
411	    let plan: BatchRunPlan
412	    let onStart: () -> Void
413	    let onCancel: () -> Void
414	
415	    private var audioPlan: BatchAudioPlan? { plan.audioPlan }
416	
417	    var body: some View {
418	        NavigationStack {
419	            Form {
420	                Section("Work to Perform") {
421	                    LabeledContent("AI Analyses", value: "\(plan.analysisCount)")
422	                    LabeledContent("New MiniMax Clips", value: "\(plan.newAudioCount)")
423	                    LabeledContent("Already Saved", value: "\(plan.cachedAudioCount)")
424	                    LabeledContent("Characters Sent", value: "\(plan.totalNewAudioCharacters)")
425	                    if let audioPlan {
426	                        LabeledContent("Mandarin Clips", value: "\(audioPlan.newMandarinClipCount)")
427	                        LabeledContent("English Clips", value: "\(audioPlan.newEnglishClipCount)")
428	                    }
429	                }
430	
431	                if let audioPlan {
432	                    Section("MiniMax Snapshot") {
433	                        // The content-closure form rather than `value:`, so the
434	                        // scope name goes through `Text`'s localizing initializer
435	                        // and follows the in-app language like the row's label.
436	                        LabeledContent("Languages") {
437	                            Text(audioPlan.scope.displayName)
438	                        }
439	                        LabeledContent("Speech Model", value: configuration?.model ?? "—")
440	                        if let mandarinVoice {
441	                            LabeledContent("Mandarin Voice", value: mandarinVoice)
442	                        }
443	                        if let englishVoice {
444	                            LabeledContent("English Voice", value: englishVoice)
445	                        }
446	                        Link(destination: pricingURL) {
447	                            Label("View MiniMax Speech Pricing", systemImage: "arrow.up.right.square")
448	                        }
449	                    }
450	                }
451	
452	                Section {
453	                    Label("Up to \(plan.newAudioCount) new paid MiniMax requests will start. Matching saved clips are excluded, duplicate terms are deduplicated, and charges may apply.", systemImage: "creditcard")
454	                        .foregroundStyle(.secondary)
455	                }
456	            }
457	            .navigationTitle("Review Batch")
458	            #if os(iOS)
459	            .navigationBarTitleDisplayMode(.inline)
460	            #elseif os(macOS)
461	            .formStyle(.grouped)
462	            .frame(minWidth: 440, minHeight: 470)
463	            #endif
464	            .toolbar {
465	                ToolbarItem(placement: .cancellationAction) {
466	                    Button("Cancel", action: onCancel)
467	                }
468	                ToolbarItem(placement: .confirmationAction) {
469	                    Button("Start Batch", action: onStart)
470	                        .disabled(!plan.hasWork)
471	                }
472	            }
473	        }
474	    }
475	
476	    private var configuration: MiniMaxSpeechConfiguration? {
477	        audioPlan?.allTargets.first?.identity.configuration
478	    }
479	
480	    private var mandarinVoice: String? {
481	        audioPlan?.allTargets.first(where: \.isMandarin)?.identity.configuration.voiceID
482	    }
483	
484	    private var englishVoice: String? {
485	        audioPlan?.allTargets.first(where: { !$0.isMandarin })?.identity.configuration.voiceID
486	    }
487	
488	    private let pricingURL = URL(string: "https://platform.minimax.io/docs/guides/pricing-speech")!
489	}
490	
491	struct BatchAIAnalysisView: View {
492	    var body: some View {
493	        Form {
494	            BatchAIAnalysisControls()
495	        }
496	        .navigationTitle("Batch AI Analysis & Audio")
497	        #if os(iOS)
498	        .navigationBarTitleDisplayMode(.inline)
499	        #endif
500	    }
501	}
