//
//  BatchExplanationController.swift
//  SwiftMandarin
//
//  Independent, resumable-by-cache batch queues for AI explanations and
//  persistent MiniMax pronunciation audio.
//

import CryptoKit
import Foundation
import Observation

nonisolated enum BatchCredentialFingerprint {
    static func make(_ credential: String) -> String {
        let normalized = credential.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !normalized.isEmpty else { return "no-credential" }
        return SHA256.hash(data: Data(normalized.utf8))
            .map { String(format: "%02x", $0) }
            .joined()
    }
}

/// An in-memory, secret-free identity for every mutable AI request setting
/// used by word explanations. The service can continue to own request
/// construction, while a reviewed batch refuses to mix models, accounts,
/// endpoints, formats, or local-Ollama options mid-run.
nonisolated struct BatchAnalysisConfigurationSnapshot: Equatable, Sendable {
    let providerRawValue: String
    let providerName: String
    let modelID: String
    let endpointIdentity: String
    let optionsIdentity: String
    let credentialFingerprint: String

    @MainActor
    static func current() -> Self {
        let settings = AIModelSettings.shared
        let provider = settings.effectiveProvider
        let modelID = settings.selectedModel(for: provider)

        switch provider {
        case .appleIntelligence:
            return Self(
                providerRawValue: provider.rawValue,
                providerName: provider.displayName,
                modelID: modelID,
                endpointIdentity: "on-device",
                optionsIdentity: "foundation-models",
                credentialFingerprint: "no-credential"
            )
        case .ollama:
            return Self(
                providerRawValue: provider.rawValue,
                providerName: provider.displayName,
                modelID: modelID,
                endpointIdentity: OllamaService.shared.hostURL.absoluteString,
                optionsIdentity: "thinking=\(settings.enableThinking);context=\(settings.contextLength)",
                credentialFingerprint: "no-credential"
            )
        default:
            let style: String
            switch settings.effectiveAPIStyle(for: provider) {
            case .openAICompatible: style = "openai"
            case .anthropic: style = "anthropic"
            }
            return Self(
                providerRawValue: provider.rawValue,
                providerName: provider.displayName,
                modelID: modelID,
                endpointIdentity: settings.baseURL(for: provider)
                    + "\u{1}" + settings.effectiveChatPath(for: provider),
                optionsIdentity: style,
                credentialFingerprint: BatchCredentialFingerprint.make(
                    settings.apiKey(for: provider)
                )
            )
        }
    }

    @MainActor
    func matchesCurrentSettings() -> Bool {
        self == Self.current()
    }
}

nonisolated struct BatchAnalysisTarget: Hashable, Sendable {
    let word: String
    let pinyin: String
    let context: String?
    let directionToken: String
}

nonisolated struct BatchRunPlan: Sendable, Identifiable {
    let id: UUID
    let analysisTargets: [BatchAnalysisTarget]
    let analysisConfiguration: BatchAnalysisConfigurationSnapshot
    let audioPlan: BatchAudioPlan?
    let audioLearningIsChinese: Bool?
    let audioCredentialFingerprint: String?

    var analysisCount: Int { analysisTargets.count }
    var newAudioCount: Int { audioPlan?.newClipCount ?? 0 }
    var cachedAudioCount: Int { audioPlan?.cachedClipCount ?? 0 }
    var totalAudioCount: Int { audioPlan?.totalClipCount ?? 0 }
    var totalNewAudioCharacters: Int { audioPlan?.totalNewCharacters ?? 0 }
    var hasWork: Bool { analysisCount > 0 || newAudioCount > 0 }
}

nonisolated struct BatchRunSummary: Equatable, Sendable {
    let analysesGenerated: Int
    let analysesFailed: Int
    let analysesSkipped: Int
    let analysesUnattempted: Int
    let audioGenerated: Int
    let audioCached: Int
    let audioFailed: Int
    let audioUnattempted: Int
}

@Observable
@MainActor
final class BatchExplanationController {
    static let shared = BatchExplanationController()

    enum RunPhase: Equatable {
        case analyzing
        case generatingAudio
    }

    enum Status: Equatable {
        case idle
        case running(RunPhase)
        case finished(BatchRunSummary)
        case cancelled(BatchRunSummary)
        case failed(BatchRunSummary)
    }

    private(set) var status: Status = .idle

    private(set) var analysisTotal = 0
    private(set) var analysesGenerated = 0
    private(set) var analysesFailed = 0
    private(set) var analysesSkipped = 0

    private(set) var audioTotal = 0
    private(set) var audioGenerated = 0
    private(set) var audioCached = 0
    private(set) var audioFailed = 0

    private(set) var lastWord: String?
    private(set) var lastErrorMessage: String?

    private var task: Task<Void, Never>?
    private var userRequestedCancellation = false
    private var stoppedByFailure = false

    private init() {}

    var isRunning: Bool {
        if case .running = status { return true }
        return false
    }

    var currentPhase: RunPhase? {
        if case let .running(phase) = status { return phase }
        return nil
    }

    var analysisProcessed: Int {
        analysesGenerated + analysesFailed + analysesSkipped
    }

    var audioProcessed: Int {
        audioGenerated + audioCached + audioFailed
    }

    var total: Int { analysisTotal + audioTotal }
    var processed: Int { analysisProcessed + audioProcessed }

    var progress: Double {
        guard total > 0 else { return 0 }
        return min(1, Double(processed) / Double(total))
    }

    var analysisProgress: Double {
        guard analysisTotal > 0 else { return 1 }
        return min(1, Double(analysisProcessed) / Double(analysisTotal))
    }

    var audioProgress: Double {
        guard audioTotal > 0 else { return 1 }
        return min(1, Double(audioProcessed) / Double(audioTotal))
    }

    func unprocessedTerms(from terms: [SavedTerm]) -> [SavedTerm] {
        let cache = WordExplanationCacheStore.shared
        return terms.filter { term in
            let word = term.headlineText
            guard !word.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return false }
            let token = ExplanationDirection.current(forWord: word).cacheToken
            return !cache.hasExplanation(forWord: word, directionToken: token)
        }
    }

    func remainingCount(from terms: [SavedTerm]) -> Int {
        unprocessedTerms(from: terms).count
    }

    /// Builds an exact, credential-free paid-request preflight. Explanation
    /// and audio queues are independent, so an audio-only run remains possible
    /// after every word has already been analyzed.
    func preparePlan(
        from terms: [SavedTerm],
        includeAudio: Bool,
        audioScope: BatchAudioScope
    ) async throws -> BatchRunPlan {
        let sorted = terms.sorted { $0.dateAdded > $1.dateAdded }
        let explanationCache = WordExplanationCacheStore.shared
        let nativeIsChinese = LocalizationManager.shared.nativeIsChinese
        let learningIsChinese = LocalizationManager.shared.learningIsChinese
        let analysisConfiguration = BatchAnalysisConfigurationSnapshot.current()
        var seenAnalyses = Set<String>()
        var analysisTargets: [BatchAnalysisTarget] = []
        var audioSnapshots: [BatchAudioTermSnapshot] = []

        for term in sorted {
            let word = term.headlineText.trimmingCharacters(in: .whitespacesAndNewlines)
            if !word.isEmpty {
                let token = ExplanationDirection(
                    wordIsChinese: word.containsCJK,
                    explainInChinese: nativeIsChinese
                ).cacheToken
                let analysisID = token + "\u{1}" + word.folding(
                    options: [.caseInsensitive, .diacriticInsensitive, .widthInsensitive],
                    locale: Locale(identifier: "en_US_POSIX")
                )
                if !explanationCache.hasExplanation(forWord: word, directionToken: token),
                   seenAnalyses.insert(analysisID).inserted {
                    analysisTargets.append(
                        BatchAnalysisTarget(
                            word: word,
                            // The reading is a sense hint for `word`, so it
                            // must belong to the side that became the headword
                            // — a Chinese-side pinyin is noise under an
                            // English headword in reverse mode.
                            pinyin: term.headwordReading,
                            context: term.glossText.isEmpty ? nil : term.glossText,
                            directionToken: token
                        )
                    )
                }
            }

            if includeAudio {
                audioSnapshots.append(
                    BatchAudioTermSnapshot(
                        termID: term.id,
                        displayWord: word.isEmpty ? term.chinese : word,
                        chineseText: term.chineseSide,
                        englishText: term.englishSide
                    )
                )
            }
        }

        let audioPlan: BatchAudioPlan?
        if includeAudio {
            let preferences = AppPreferences.shared
            let chineseConfiguration = preferences.miniMaxSpeechConfiguration(languageCode: "zh-CN")
            let englishConfiguration = preferences.miniMaxSpeechConfiguration(languageCode: "en-US")
            let uncachedPlan = BatchAudioPlanner.makePlan(
                terms: audioSnapshots,
                scope: audioScope,
                learningIsChinese: learningIsChinese,
                chineseConfiguration: chineseConfiguration,
                englishConfiguration: englishConfiguration,
                existingRecordIDs: []
            )
            let existing = try await GeneratedSpeechRepository.shared.existingRecordIDs(
                among: Set(uncachedPlan.allTargets.map(\.id))
            )
            audioPlan = BatchAudioPlanner.makePlan(
                terms: audioSnapshots,
                scope: audioScope,
                learningIsChinese: learningIsChinese,
                chineseConfiguration: chineseConfiguration,
                englishConfiguration: englishConfiguration,
                existingRecordIDs: existing
            )
        } else {
            audioPlan = nil
        }

        return BatchRunPlan(
            id: UUID(),
            analysisTargets: analysisTargets,
            analysisConfiguration: analysisConfiguration,
            audioPlan: audioPlan,
            audioLearningIsChinese: includeAudio ? learningIsChinese : nil,
            audioCredentialFingerprint: includeAudio
                ? BatchCredentialFingerprint.make(
                    AIModelSettings.shared.apiKey(for: .minimax)
                )
                : nil
        )
    }

    func start(plan: BatchRunPlan, concurrency: Int) {
        guard !isRunning else { return }

        let settings = AIModelSettings.shared
        if plan.analysisCount > 0, !settings.isAnyProviderAvailable {
            resetCounters(for: plan)
            lastErrorMessage = String(localized: "No AI provider is configured. Add one in Settings → AI (or run a local Ollama server).", bundle: .appLanguage)
            status = .failed(summary())
            return
        }

        if plan.analysisCount > 0,
           !plan.analysisConfiguration.matchesCurrentSettings() {
            resetCounters(for: plan)
            lastErrorMessage = String(localized: "AI settings changed after this batch was reviewed. Review the batch again before starting.", bundle: .appLanguage)
            status = .failed(summary())
            return
        }

        if plan.analysisTargets.contains(where: {
            ExplanationDirection.current(forWord: $0.word).cacheToken != $0.directionToken
        }) {
            resetCounters(for: plan)
            lastErrorMessage = String(localized: "Language settings changed after this batch was reviewed. Review the batch again before starting.", bundle: .appLanguage)
            status = .failed(summary())
            return
        }

        if plan.audioPlan?.scope == .learningLanguage,
           plan.audioLearningIsChinese != LocalizationManager.shared.learningIsChinese {
            resetCounters(for: plan)
            lastErrorMessage = String(localized: "Language settings changed after this batch was reviewed. Review the batch again before starting.", bundle: .appLanguage)
            status = .failed(summary())
            return
        }

        let apiKey = plan.newAudioCount > 0 ? settings.apiKey(for: .minimax) : ""
        if plan.newAudioCount > 0,
           apiKey.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            resetCounters(for: plan)
            lastErrorMessage = String(localized: "Add a MiniMax API key in AI Audio settings before generating batch audio.", bundle: .appLanguage)
            status = .failed(summary())
            return
        }
        if plan.newAudioCount > 0,
           plan.audioCredentialFingerprint != BatchCredentialFingerprint.make(apiKey) {
            resetCounters(for: plan)
            lastErrorMessage = String(localized: "The MiniMax API key changed after this batch was reviewed. Review the batch again before starting.", bundle: .appLanguage)
            status = .failed(summary())
            return
        }

        let analysisLimit = min(
            max(concurrency, AIModelSettings.batchConcurrencyRange.lowerBound),
            AIModelSettings.batchConcurrencyRange.upperBound
        )
        resetCounters(for: plan)
        guard plan.hasWork else {
            status = .finished(summary())
            return
        }

        status = .running(plan.analysisCount > 0 ? .analyzing : .generatingAudio)
        task = Task { [weak self] in
            await self?.run(
                plan: plan,
                analysisConcurrency: analysisLimit,
                apiKey: apiKey,
                analysisConfiguration: plan.analysisConfiguration
            )
        }
    }

    func cancel() {
        userRequestedCancellation = true
        task?.cancel()
    }

    private func resetCounters(for plan: BatchRunPlan) {
        analysisTotal = plan.analysisCount
        analysesGenerated = 0
        analysesFailed = 0
        analysesSkipped = 0
        audioTotal = plan.totalAudioCount
        audioGenerated = 0
        audioCached = plan.cachedAudioCount
        audioFailed = 0
        lastWord = nil
        lastErrorMessage = nil
        userRequestedCancellation = false
        stoppedByFailure = false
    }

    private func run(
        plan: BatchRunPlan,
        analysisConcurrency: Int,
        apiKey: String,
        analysisConfiguration: BatchAnalysisConfigurationSnapshot
    ) async {
        let runtimeAudioPlan: BatchAudioPlan?
        do {
            if let reviewedAudioPlan = plan.audioPlan {
                let existing = try await GeneratedSpeechRepository.shared.existingRecordIDs(
                    among: Set(reviewedAudioPlan.allTargets.map(\.id))
                )
                runtimeAudioPlan = try BatchAudioPlanRevalidator.revalidate(
                    reviewed: reviewedAudioPlan,
                    existingRecordIDs: existing
                )
                audioCached = runtimeAudioPlan?.cachedClipCount ?? 0
            } else {
                runtimeAudioPlan = nil
            }
        } catch is CancellationError {
            finish()
            return
        } catch {
            stoppedByFailure = true
            lastErrorMessage = error.localizedDescription
            finish()
            return
        }

        if Task.isCancelled {
            finish()
            return
        }

        if !plan.analysisTargets.isEmpty {
            await runAnalyses(
                plan.analysisTargets,
                concurrency: analysisConcurrency,
                analysisConfiguration: analysisConfiguration
            )
        }

        if !Task.isCancelled,
           let audioPlan = runtimeAudioPlan,
           !audioPlan.pendingTargets.isEmpty {
            status = .running(.generatingAudio)
            await runAudio(
                audioPlan.pendingTargets,
                apiKey: apiKey,
                credentialFingerprint: plan.audioCredentialFingerprint
                    ?? BatchCredentialFingerprint.make(apiKey)
            )
        }

        finish()
    }

    private enum AnalysisOutcome: Sendable {
        case generated(word: String)
        case failed(word: String, message: String, stopRemaining: Bool)
        case skipped
        case cancelled
    }

    private func runAnalyses(
        _ targets: [BatchAnalysisTarget],
        concurrency: Int,
        analysisConfiguration: BatchAnalysisConfigurationSnapshot
    ) async {
        await withTaskGroup(of: AnalysisOutcome.self) { group in
            var nextIndex = 0

            func addTaskIfPossible() {
                guard nextIndex < targets.count, !Task.isCancelled else { return }
                let target = targets[nextIndex]
                nextIndex += 1
                group.addTask {
                    await Self.processAnalysis(
                        target,
                        analysisConfiguration: analysisConfiguration
                    )
                }
            }

            for _ in 0..<concurrency { addTaskIfPossible() }
            while let outcome = await group.next() {
                apply(outcome)
                if Task.isCancelled {
                    group.cancelAll()
                } else {
                    addTaskIfPossible()
                }
            }
        }
    }

    @MainActor
    private static func processAnalysis(
        _ target: BatchAnalysisTarget,
        analysisConfiguration: BatchAnalysisConfigurationSnapshot
    ) async -> AnalysisOutcome {
        if Task.isCancelled { return .cancelled }
        guard analysisConfiguration.matchesCurrentSettings(),
              ExplanationDirection.current(forWord: target.word).cacheToken == target.directionToken else {
            return .failed(
                word: target.word,
                message: String(localized: "AI or language settings changed while the batch was running. Start a new reviewed batch to continue.", bundle: .appLanguage),
                stopRemaining: true
            )
        }
        let cache = WordExplanationCacheStore.shared
        if cache.hasExplanation(forWord: target.word, directionToken: target.directionToken) {
            return .skipped
        }

        do {
            let result = try await AIWordExplanationService.shared.generateExplanationWithProvider(
                for: target.word,
                pinyin: target.pinyin,
                context: target.context
            )
            if Task.isCancelled { return .cancelled }
            guard analysisConfiguration.matchesCurrentSettings(),
                  ExplanationDirection.current(forWord: target.word).cacheToken == target.directionToken else {
                return .failed(
                    word: target.word,
                    message: String(localized: "AI or language settings changed while the batch was running. The completed response was not cached under stale settings.", bundle: .appLanguage),
                    stopRemaining: true
                )
            }
            cache.store(
                word: target.word,
                pinyin: target.pinyin,
                directionToken: target.directionToken,
                providerName: analysisConfiguration.providerName,
                result: result
            )
            return .generated(word: target.word)
        } catch is CancellationError {
            return .cancelled
        } catch {
            if Task.isCancelled { return .cancelled }
            return .failed(
                word: target.word,
                message: error.localizedDescription,
                stopRemaining: false
            )
        }
    }

    private func apply(_ outcome: AnalysisOutcome) {
        switch outcome {
        case let .generated(word):
            analysesGenerated += 1
            lastWord = word
        case let .failed(word, message, stopRemaining):
            analysesFailed += 1
            lastWord = word
            lastErrorMessage = message
            if stopRemaining {
                stopForFailure()
            }
        case .skipped:
            analysesSkipped += 1
        case .cancelled:
            break
        }
    }

    private enum AudioOutcome: Sendable {
        case generated(record: GeneratedSpeechRecord, word: String, wasCached: Bool)
        case failed(word: String, message: String, stopRemaining: Bool)
        case cancelled
    }

    private func runAudio(
        _ targets: [BatchAudioTarget],
        apiKey: String,
        credentialFingerprint: String
    ) async {
        let gate = BatchAudioStartGate()
        await withTaskGroup(of: AudioOutcome.self) { group in
            var nextIndex = 0
            let concurrency = min(2, targets.count)

            func addTaskIfPossible() {
                guard nextIndex < targets.count, !Task.isCancelled else { return }
                let target = targets[nextIndex]
                nextIndex += 1
                group.addTask {
                    await Self.processAudio(
                        target,
                        apiKey: apiKey,
                        credentialFingerprint: credentialFingerprint,
                        gate: gate
                    )
                }
            }

            for _ in 0..<concurrency { addTaskIfPossible() }
            while let outcome = await group.next() {
                apply(outcome)
                if Task.isCancelled {
                    group.cancelAll()
                } else {
                    addTaskIfPossible()
                }
            }
        }
    }

    @MainActor
    private static func processAudio(
        _ target: BatchAudioTarget,
        apiKey: String,
        credentialFingerprint: String,
        gate: BatchAudioStartGate
    ) async -> AudioOutcome {
        if Task.isCancelled { return .cancelled }
        do {
            try await gate.waitForPermit()
            guard credentialFingerprint == BatchCredentialFingerprint.make(apiKey),
                  credentialFingerprint == BatchCredentialFingerprint.make(
                    AIModelSettings.shared.apiKey(for: .minimax)
                  ) else {
                return .failed(
                    word: target.displayWord,
                    message: String(localized: "The MiniMax API key changed while the batch was running. Start a new reviewed batch to continue.", bundle: .appLanguage),
                    stopRemaining: true
                )
            }
            let generated = try await MiniMaxSpeechPipeline.shared.speech(
                for: target.identity,
                apiKey: apiKey
            )
            GeneratedSpeechStore.shared.note(generated.record)
            return .generated(
                record: generated.record,
                word: target.displayWord,
                wasCached: generated.wasCached
            )
        } catch is CancellationError {
            return .cancelled
        } catch MiniMaxAudioError.cancelled {
            return .cancelled
        } catch {
            if Task.isCancelled { return .cancelled }
            return .failed(
                word: target.displayWord,
                message: error.localizedDescription,
                stopRemaining: BatchAudioFailurePolicy.shouldStop(after: error)
            )
        }
    }

    private func apply(_ outcome: AudioOutcome) {
        switch outcome {
        case let .generated(_, word, wasCached):
            if wasCached {
                audioCached += 1
            } else {
                audioGenerated += 1
            }
            lastWord = word
        case let .failed(word, message, stopRemaining):
            audioFailed += 1
            lastWord = word
            lastErrorMessage = message
            if stopRemaining {
                // Authentication, configuration, quota, and rate-limit errors
                // affect the remaining queue. Stop before repeating the same
                // failing paid request; a later run resumes from saved clips.
                stopForFailure()
            }
        case .cancelled:
            break
        }
    }

    private func summary() -> BatchRunSummary {
        BatchRunSummary(
            analysesGenerated: analysesGenerated,
            analysesFailed: analysesFailed,
            analysesSkipped: analysesSkipped,
            analysesUnattempted: max(0, analysisTotal - analysisProcessed),
            audioGenerated: audioGenerated,
            audioCached: audioCached,
            audioFailed: audioFailed,
            audioUnattempted: max(0, audioTotal - audioProcessed)
        )
    }

    private func finish() {
        let finalSummary = summary()
        if stoppedByFailure {
            status = .failed(finalSummary)
        } else if userRequestedCancellation || Task.isCancelled {
            status = .cancelled(finalSummary)
        } else {
            status = .finished(finalSummary)
        }
        task = nil
    }

    private func stopForFailure() {
        stoppedByFailure = true
        task?.cancel()
    }
}

//
//  WordExplanationCacheStore.swift
//  SwiftMandarin
//
//  Persistent cache for AI-generated word explanations. Generating an
//  explanation is slow and (for cloud providers) costs API tokens, so once a
//  word has been explained the result is stored and re-served instantly the
//  next time that word is opened — until the user explicitly regenerates it.
//

import Foundation
import os.log

// MARK: - Cached Entry

/// One persisted AI word explanation plus the metadata needed to key and label
/// it. Entries are keyed by the (normalized word, direction) pair: toggling the
/// interface language flips the language the explanation is written in, so a
/// per-direction key prevents serving a stale-direction explanation.
struct CachedWordExplanation: Codable, Equatable, Sendable {
    /// The exact word that was explained (original casing/script preserved for
    /// display; matching is done on a normalized form).
    let word: String
    let pinyin: String
    /// Direction token from `ExplanationDirection.cacheToken`
    /// (e.g. `"zh>en"` — Chinese word explained in English).
    let directionToken: String
    /// Display name of the provider that generated this explanation.
    let providerName: String
    /// When the explanation was generated, shown so the user can judge staleness.
    let generatedAt: Date
    let result: WordExplanationResult

    init(
        word: String,
        pinyin: String,
        directionToken: String,
        providerName: String,
        generatedAt: Date,
        result: WordExplanationResult
    ) {
        self.word = word
        self.pinyin = pinyin
        self.directionToken = directionToken
        self.providerName = providerName
        self.generatedAt = generatedAt
        self.result = result
    }

    private enum CodingKeys: String, CodingKey {
        case word, pinyin, directionToken, providerName, generatedAt, result
    }

    /// Tolerant decode: only `word` and `result` are essential. A payload
    /// written by an older build (missing a field added later) still loads with
    /// sensible defaults instead of failing — and one bad field never discards
    /// the rest of the entry.
    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        word = try container.decode(String.self, forKey: .word)
        result = try container.decode(WordExplanationResult.self, forKey: .result)
        pinyin = (try? container.decode(String.self, forKey: .pinyin)) ?? ""
        directionToken = (try? container.decode(String.self, forKey: .directionToken)) ?? ""
        providerName = (try? container.decode(String.self, forKey: .providerName)) ?? ""
        generatedAt = (try? container.decode(Date.self, forKey: .generatedAt))
            ?? Date(timeIntervalSince1970: 0)
    }
}

// MARK: - Cache Store

/// MainActor-isolated cache of word explanations, persisted to a JSON file in
/// Application Support. There is **no capacity limit** — every word the user
/// analyzes is retained, so a batch run's progress is permanent and the
/// "analyzed" count reflects reality rather than a cache ceiling. (An earlier
/// version capped this at 400 entries on an MRU basis, which silently evicted
/// older analyses and made the batch-progress count stick at 400.)
///
/// Two design points keep it fast at thousands of entries: the `lookupIndex`
/// membership set is maintained incrementally (never rebuilt per mutation), and
/// disk writes are coalesced and performed off the main thread.
@Observable
@MainActor
final class WordExplanationCacheStore {
    static let shared = WordExplanationCacheStore()

    /// All cached explanations. Order is insignificant — lookups go through
    /// `lookupIndex` (membership) or a linear scan (single-word reads, rare).
    private(set) var entries: [CachedWordExplanation] = []

    /// O(1) membership set of `"<directionToken>\u{1}<normalizedWord>"`.
    /// Maintained incrementally alongside `entries`: rebuilding it on every
    /// mutation would make a batch over N words O(N²) and saturate the main
    /// thread. Observed (not ignored) so the live "remaining" count updates as
    /// analyses are stored.
    private var lookupIndex: Set<String> = []

    /// O(1) membership set of normalized headwords across ALL directions, so
    /// "does this word have any analysis?" (used by the export count) is O(1)
    /// instead of an O(entries) scan per term.
    private var normalizedWordIndex: Set<String> = []

    /// Legacy UserDefaults key, read once at launch to migrate into the file.
    private let legacyDefaultsKey = "wordExplanationCache"
    /// On-disk JSON store in Application Support.
    private let fileName = "word-explanation-cache.json"

    /// Coalesced + throttled single-writer persistence: a running write task
    /// drains `needsWrite`, collapsing bursts of mutations into at most one
    /// off-main write per `writeThrottle` while still guaranteeing the final
    /// state reaches disk. Throttling matters because a batch over thousands of
    /// words re-encodes the whole (growing) file each write — without it that is
    /// O(n²) bytes of disk I/O.
    private var writeTask: Task<Void, Never>?
    private var needsWrite = false
    private static let writeThrottle: Duration = .seconds(10)

    nonisolated private static let log = Logger(subsystem: "com.rogerlin.SwiftMandarin", category: "WordExplanationCache")

    private init() {
        load()
    }

    // MARK: Queries

    var count: Int { entries.count }
    var isEmpty: Bool { entries.isEmpty }

    private static func lookupKey(directionToken: String, word: String) -> String {
        "\(directionToken)\u{1}\(normalizedKey(word))"
    }

    private func rebuildLookupIndex() {
        lookupIndex = Set(entries.map { Self.lookupKey(directionToken: $0.directionToken, word: $0.word) })
        normalizedWordIndex = Set(entries.map { Self.normalizedKey($0.word) })
    }

    /// Return a cached explanation for `word` in the given direction, if one
    /// exists. Matching ignores invisible characters and surrounding
    /// whitespace, and is case-insensitive (English headwords).
    func explanation(forWord word: String, directionToken: String) -> CachedWordExplanation? {
        let key = Self.normalizedKey(word)
        return entries.first {
            $0.directionToken == directionToken && Self.normalizedKey($0.word) == key
        }
    }

    /// Whether an explanation is cached for `word` in the given direction.
    /// O(1) via `lookupIndex` — this is the batch hot path.
    func hasExplanation(forWord word: String, directionToken: String) -> Bool {
        lookupIndex.contains(Self.lookupKey(directionToken: directionToken, word: word))
    }

    /// Every cached explanation whose headword matches any of `words` (across
    /// all directions). Used by export to bundle a term's AI analysis: a term's
    /// explanation may be stored under either learning-direction headword, so
    /// callers pass all candidate forms (see `SavedTerm.aiCacheCandidateWords`).
    func explanations(forWords words: [String]) -> [CachedWordExplanation] {
        let keys = Set(words.map(Self.normalizedKey)).subtracting([""])
        guard !keys.isEmpty else { return [] }
        return entries.filter { keys.contains(Self.normalizedKey($0.word)) }
    }

    /// Whether any of `words` has a cached explanation in any direction. O(1) per
    /// word via `normalizedWordIndex` — used by the export count, which would
    /// otherwise scan all entries once per term.
    func hasAnyExplanation(forWords words: [String]) -> Bool {
        for word in words {
            let key = Self.normalizedKey(word)
            if !key.isEmpty && normalizedWordIndex.contains(key) { return true }
        }
        return false
    }

    // MARK: Mutations

    /// Insert or replace the explanation for `(word, directionToken)`. A new
    /// word is appended (O(1) — the batch hot path); re-analyzing an existing
    /// word replaces it in place. There is no capacity trimming.
    func store(
        word: String,
        pinyin: String,
        directionToken: String,
        providerName: String,
        result: WordExplanationResult,
        generatedAt: Date = Date()
    ) {
        let entry = CachedWordExplanation(
            word: word,
            pinyin: pinyin,
            directionToken: directionToken,
            providerName: providerName,
            generatedAt: generatedAt,
            result: result
        )
        upsert(entry)
        scheduleSave()
    }

    /// Merge imported explanations into the cache in a single pass (one save).
    /// Each incoming entry replaces any existing entry with the same
    /// (word, direction) key. Used by vocabulary import so a restore of N
    /// analyses costs one write, not N.
    func merge(_ incoming: [CachedWordExplanation]) {
        guard !incoming.isEmpty else { return }
        for entry in incoming {
            upsert(entry)
        }
        scheduleSave()
    }

    /// Insert `entry`, or replace the existing entry with the same
    /// (word, direction) key in place, keeping `lookupIndex` in lockstep. Does
    /// not persist — callers invoke `scheduleSave()` once after a batch of
    /// upserts.
    private func upsert(_ entry: CachedWordExplanation) {
        let lk = Self.lookupKey(directionToken: entry.directionToken, word: entry.word)
        if lookupIndex.contains(lk) {
            let key = Self.normalizedKey(entry.word)
            if let idx = entries.firstIndex(where: {
                $0.directionToken == entry.directionToken && Self.normalizedKey($0.word) == key
            }) {
                entries[idx] = entry
                return
            }
        }
        entries.append(entry)
        lookupIndex.insert(lk)
        normalizedWordIndex.insert(Self.normalizedKey(entry.word))
    }

    /// Remove the cached explanation for a specific word+direction (e.g. when
    /// its saved term is deleted).
    func remove(word: String, directionToken: String) {
        let key = Self.normalizedKey(word)
        let updated = entries.filter {
            !($0.directionToken == directionToken && Self.normalizedKey($0.word) == key)
        }
        guard updated.count != entries.count else { return }
        entries = updated
        rebuildLookupIndex()
        scheduleSave()
    }

    /// Remove every cached explanation for `word`, regardless of direction.
    func removeAll(forWord word: String) {
        let key = Self.normalizedKey(word)
        let updated = entries.filter { Self.normalizedKey($0.word) != key }
        guard updated.count != entries.count else { return }
        entries = updated
        rebuildLookupIndex()
        scheduleSave()
    }

    func clear() {
        guard !entries.isEmpty else { return }
        entries = []
        lookupIndex = []
        normalizedWordIndex = []
        scheduleSave()
    }

    // MARK: Private

    /// Normalize a word for cache lookup: strip zero-width characters and BOM
    /// (AI/OCR sources attach these), trim whitespace, and lowercase so English
    /// headwords match regardless of capitalization.
    private static func normalizedKey(_ s: String) -> String {
        String(s.unicodeScalars.filter { ![0x200B, 0x200C, 0x200D, 0xFEFF].contains($0.value) })
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
    }

    // MARK: Persistence (file-backed, coalesced, off the main thread)

    /// Request a persist. Encoding the (potentially large) entries array and
    /// writing it happen off the main thread; writes are coalesced so a batch
    /// that stores thousands of words doesn't re-encode the file thousands of
    /// times on the main actor.
    private func scheduleSave() {
        needsWrite = true
        guard writeTask == nil else { return }
        writeTask = Task { [weak self] in
            guard let self else { return }
            while self.needsWrite {
                self.needsWrite = false
                let snapshot = self.entries      // value-type COW snapshot (cheap)
                let name = self.fileName
                // Encode + write off the main actor; only Sendable values cross.
                _ = await Task.detached(priority: .utility) {
                    Self.writeToDisk(snapshot, fileName: name)
                }.value
                // Throttle: if more mutations arrived, wait so a burst (e.g. a
                // batch run) coalesces into one write per interval instead of
                // re-encoding the whole growing file per word. A trailing write
                // always follows the last mutation, so nothing is lost.
                if self.needsWrite {
                    try? await Task.sleep(for: Self.writeThrottle)
                }
            }
            self.writeTask = nil
        }
    }

    /// Encode and atomically write the cache. Returns whether it succeeded, so
    /// the migration can avoid deleting its source on a failed write.
    @discardableResult
    nonisolated private static func writeToDisk(_ entries: [CachedWordExplanation], fileName: String) -> Bool {
        guard let url = PersistentCodableStore.appSupportFileURL(fileName) else { return false }
        do {
            let data = try JSONEncoder().encode(entries)
            try data.write(to: url, options: .atomic)
            return true
        } catch {
            // The cache is regenerable; a failed write just means a word may be
            // re-analyzed later. Don't crash or block on it.
            log.error("WordExplanationCache write failed: \(error.localizedDescription, privacy: .public)")
            return false
        }
    }

    private func load() {
        // Preferred: the file-backed store.
        if let loaded = PersistentCodableStore.loadArrayFromFile([CachedWordExplanation].self, fileName: fileName) {
            entries = loaded
            rebuildLookupIndex()
            return
        }
        // One-time migration from the old UserDefaults-backed cache (≤ the old
        // 400-entry cap). Adopt it, write it to the file, and only when that
        // write succeeds clear the UserDefaults keys — otherwise leave them so
        // the migration retries next launch rather than losing the data.
        if let legacy = PersistentCodableStore.load([CachedWordExplanation].self, key: legacyDefaultsKey) {
            entries = legacy
            rebuildLookupIndex()
            if Self.writeToDisk(legacy, fileName: fileName) {   // small; fine during init
                UserDefaults.standard.removeObject(forKey: legacyDefaultsKey)
                UserDefaults.standard.removeObject(forKey: legacyDefaultsKey + ".backup")
            }
        }
    }
}

//
//  SavedTerm.swift
//  SwiftMandarin
//
//  Model for saved vocabulary terms
//

import Foundation
import SwiftUI
import Observation

struct SavedTerm: Identifiable, Codable, Equatable, Hashable {
    let id: UUID
    let chinese: String
    let pinyin: String
    let definition: String
    let partOfSpeech: String
    let dateAdded: Date
    var sortOrder: Int
    var isMastered: Bool

    init(
        id: UUID = UUID(),
        chinese: String,
        pinyin: String,
        definition: String,
        partOfSpeech: String = "",
        dateAdded: Date = Date(),
        sortOrder: Int = 0,
        isMastered: Bool = false
    ) {
        self.id = id
        self.chinese = chinese
        self.pinyin = pinyin
        self.definition = definition
        self.partOfSpeech = partOfSpeech
        self.dateAdded = dateAdded
        self.sortOrder = sortOrder
        self.isMastered = isMastered
    }

    private enum CodingKeys: String, CodingKey {
        case id, chinese, pinyin, definition, partOfSpeech, dateAdded, sortOrder, isMastered
    }

    /// Tolerant decoder: a missing or malformed field falls back to a default
    /// rather than throwing and dropping the whole saved term.
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = (try? c.decode(UUID.self, forKey: .id)) ?? UUID()
        chinese = (try? c.decode(String.self, forKey: .chinese)) ?? ""
        pinyin = (try? c.decode(String.self, forKey: .pinyin)) ?? ""
        definition = (try? c.decode(String.self, forKey: .definition)) ?? ""
        partOfSpeech = (try? c.decode(String.self, forKey: .partOfSpeech)) ?? ""
        dateAdded = (try? c.decode(Date.self, forKey: .dateAdded)) ?? Date()
        sortOrder = (try? c.decode(Int.self, forKey: .sortOrder)) ?? 0
        isMastered = (try? c.decode(Bool.self, forKey: .isMastered)) ?? false
    }
}

// MARK: - Interface-language-aware display

/// The `chinese` field is really a *headword*: photo-extraction and workbook
/// flows store English headwords there when the user is learning English. So
/// the two display sides are detected from content, and which side is the big
/// headline follows the interface language (= the user's native language):
/// 中文 UI → learning English → English is the headline, Mandarin the gloss;
/// English UI → learning Mandarin → Chinese headline + pinyin, English gloss.
extension SavedTerm {

    /// The Chinese side of the entry (headword preferred, else definition).
    var chineseSide: String {
        if chinese.containsCJK { return chinese }
        if definition.containsCJK { return definition }
        return ""
    }

    /// The English side of the entry (headword preferred, else definition).
    var englishSide: String {
        if !chinese.containsCJK, !chinese.isEmpty { return chinese }
        if !definition.containsCJK { return definition }
        return ""
    }

    /// The text shown big — the side in the language the user is learning.
    ///
    /// A one-sided entry (saved before the learner switched direction, or
    /// captured with only a headword) has nothing in the studied language. It
    /// still has to render *something*, so the other side is promoted rather
    /// than leaving a blank row — and `glossText` then correctly returns "",
    /// because the promoted text is already on screen.
    @MainActor
    var headlineText: String {
        let context = LearningContext.current
        let primary = context.primary(chinese: chineseSide, english: englishSide)
        guard primary.isEmpty else { return primary }
        let fallback = context.secondary(chinese: chineseSide, english: englishSide)
        return fallback.isEmpty ? chinese : fallback
    }

    /// The small secondary text — the side in the user's native language.
    /// Empty when the entry has nothing beyond the headline.
    @MainActor
    var glossText: String {
        let secondary = LearningContext.current.secondary(chinese: chineseSide, english: englishSide)
        return secondary == headlineText ? "" : secondary
    }

    /// Pinyin is a learner aid for reading Chinese: shown only when the user
    /// is learning Chinese (English UI) and the entry has a Chinese side.
    ///
    /// The mirror aid — an English pronunciation for a Mandarin speaker — is
    /// `showsPhonetic`, since the two are never useful at the same time.
    @MainActor
    var showsPinyin: Bool {
        LearningContext.current.showsPinyinAffordances && !chineseSide.isEmpty && !pinyin.isEmpty
    }

    /// Whether the stored reading should be shown as an English pronunciation
    /// under an English headword.
    ///
    /// In reverse mode the AI fills the same `pinyin` slot with IPA (see
    /// `AIExplanationPromptBuilder`), so no new storage is needed — only a
    /// rule for when to read it that way. The `looksLikeIPA` guard matters:
    /// a term saved while learning Mandarin holds *pinyin* there, and showing
    /// "xuéxí" under the headword "study" would be worse than showing nothing.
    @MainActor
    var showsPhonetic: Bool {
        !LearningContext.current.showsPinyinAffordances
            && !englishSide.isEmpty
            && pinyin.looksLikeIPA
            && headlineText == englishSide
    }

    /// The stored reading, but only when it actually belongs to `headlineText`.
    ///
    /// One field holds the reading for both directions, so an entry saved
    /// while learning Mandarin carries pinyin for its Chinese side. Handing
    /// that to an explanation request for the English headword — where it is
    /// read as a sense hint — would be misleading noise, and pasting it into a
    /// copied English word would be nonsense. Empty when the two don't match.
    @MainActor
    var headwordReading: String {
        if showsPinyin, headlineText == chineseSide { return pinyin }
        if showsPhonetic { return pinyin }
        return ""
    }

    /// Headword forms an AI explanation might be cached under. The analyzed word
    /// is `headlineText`, which is either side depending on the learning
    /// direction at generation time, so export gathers explanations matching any
    /// of these (deduplicated, non-empty). Non-isolated so it is usable off the
    /// main actor (it reads only content-derived sides, not the interface
    /// language).
    var aiCacheCandidateWords: [String] {
        var seen = Set<String>()
        var out: [String] = []
        for candidate in [chinese, chineseSide, englishSide] {
            let trimmed = candidate.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmed.isEmpty, seen.insert(trimmed).inserted else { continue }
            out.append(trimmed)
        }
        return out
    }
}

// MARK: - Saved Terms Store

@Observable
@MainActor
final class SavedTermsStore {
    static let shared = SavedTermsStore()

    var terms: [SavedTerm] = [] {
        didSet { save() }
    }

    /// Public accessor for saved terms (alias for terms)
    var savedTerms: [SavedTerm] { terms }

    private let saveKey = "savedTerms"

    private init() {
        load()
    }

    // MARK: - Public Methods

    /// Normalize a term for duplicate comparison: AI/OCR sources can attach
    /// invisible characters (zero-width space/joiners, BOM) or stray
    /// whitespace, which would defeat plain string equality.
    ///
    /// Case is folded too. Han characters have no case, so this changes
    /// nothing for a Mandarin headword — but an English headword captured at
    /// the start of a sentence ("Charge") would otherwise be stored a second
    /// time alongside the same word met mid-sentence ("charge"). This mirrors
    /// `WordExplanationCacheStore`, which already folds case for the same
    /// reason.
    private static func normalizedKey(_ s: String) -> String {
        String(s.unicodeScalars.filter { ![0x200B, 0x200C, 0x200D, 0xFEFF].contains($0.value) })
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
    }

    func add(_ term: SavedTerm) {
        let key = Self.normalizedKey(term.chinese)
        guard !terms.contains(where: { Self.normalizedKey($0.chinese) == key }) else { return }
        var newTerm = term
        newTerm.sortOrder = terms.count
        terms.append(newTerm)
        // Track activity with part of speech
        LearningActivityStore.shared.recordWordLearned(partOfSpeech: term.partOfSpeech)
    }

    func add(chinese: String, pinyin: String, definition: String, partOfSpeech: String = "") {
        let key = Self.normalizedKey(chinese)
        guard !terms.contains(where: { Self.normalizedKey($0.chinese) == key }) else { return }

        let newTerm = SavedTerm(
            chinese: chinese,
            pinyin: pinyin,
            definition: definition,
            partOfSpeech: partOfSpeech,
            sortOrder: terms.count
        )
        terms.append(newTerm)
        // Track activity with part of speech
        LearningActivityStore.shared.recordWordLearned(partOfSpeech: partOfSpeech)
    }

    func remove(at offsets: IndexSet) {
        var updated = terms
        let removed = offsets.compactMap { terms.indices.contains($0) ? terms[$0] : nil }
        updated.remove(atOffsets: offsets)
        terms = reindexed(updated)
        purgeProgress(for: removed)
    }

    func remove(_ term: SavedTerm) {
        terms = reindexed(terms.filter { $0.id != term.id })
        purgeProgress(for: [term])
    }

    func remove(chinese: String) {
        let key = Self.normalizedKey(chinese)
        let removed = terms.filter { Self.normalizedKey($0.chinese) == key }
        terms = reindexed(terms.filter { Self.normalizedKey($0.chinese) != key })
        purgeProgress(for: removed)
    }

    func term(withID id: UUID) -> SavedTerm? {
        terms.first { $0.id == id }
    }

    /// Replace a stored term. Returns `false` when the term no longer exists
    /// (e.g. it was deleted while a detail view held a stale copy), so callers
    /// can surface the failure instead of silently dropping the edit.
    @discardableResult
    func update(_ updatedTerm: SavedTerm) -> Bool {
        guard let index = terms.firstIndex(where: { $0.id == updatedTerm.id }) else { return false }

        var replacement = updatedTerm
        replacement.sortOrder = terms[index].sortOrder
        terms[index] = replacement
        return true
    }

    func move(from source: Int, to destination: Int) {
        var updated = terms
        updated.move(fromOffsets: IndexSet(integer: source), toOffset: destination)
        terms = reindexed(updated)
    }

    func contains(chinese: String) -> Bool {
        let key = Self.normalizedKey(chinese)
        return terms.contains { Self.normalizedKey($0.chinese) == key }
    }

    func clear() {
        let removed = terms
        terms.removeAll()
        purgeProgress(for: removed)
    }

    /// Toggle the mastered status of a term
    func toggleMastered(_ term: SavedTerm) {
        guard let index = terms.firstIndex(where: { $0.id == term.id }) else { return }
        terms[index].isMastered.toggle()
    }

    /// Set the mastered status of a term
    func setMastered(_ term: SavedTerm, isMastered: Bool) {
        guard let index = terms.firstIndex(where: { $0.id == term.id }) else { return }
        terms[index].isMastered = isMastered
    }

    /// Count of mastered terms
    var masteredCount: Int {
        terms.filter { $0.isMastered }.count
    }

    // MARK: - Private Methods

    /// Purge the SRS review progress of removed terms. Vocabulary cards are
    /// keyed "vocab:<uuid>" in `LearningProgressStore`, so without this a
    /// deleted word would leave an orphaned card that keeps resurfacing in
    /// due/review queues forever.
    private func purgeProgress(for removed: [SavedTerm]) {
        for term in removed {
            LearningProgressStore.shared.removeProgress(forCardId: "vocab:\(term.id.uuidString)")
        }
    }

    /// Return a copy of `terms` with `sortOrder` renumbered to match array
    /// position. Callers assign the result to `terms` in a single statement so
    /// the `didSet` persistence hook fires exactly once. Renumbering in place
    /// (`terms[i].sortOrder = i` in a loop) instead triggers `save()` for every
    /// row, turning one delete into an O(n²) synchronous JSON-encode +
    /// UserDefaults write storm that freezes the UI on large lists.
    private func reindexed(_ source: [SavedTerm]) -> [SavedTerm] {
        var result = source
        for index in result.indices {
            result[index].sortOrder = index
        }
        return result
    }

    private func save() {
        PersistentCodableStore.save(terms, key: saveKey)
    }

    private func load() {
        if let decoded = PersistentCodableStore.load([SavedTerm].self, key: saveKey) {
            terms = decoded.sorted { $0.sortOrder < $1.sortOrder }
        }
    }
}

//
//  AIModelSettings.swift
//  SwiftMandarin
//
//  Manages AI provider settings and preferences. Supports Apple Intelligence
//  (Foundation Models), local Ollama, and a family of cloud providers
//  (OpenAI, Anthropic/Claude, Deepseek, Doubao, Qwen, Kimi, Zhipu, Minimax)
//  reached over their REST APIs. API keys are stored in the Keychain.
//

import Foundation
import SwiftUI

// MARK: - Provider API Style

/// The request/response convention a cloud provider uses.
enum AIProviderAPIStyle {
    /// OpenAI `/chat/completions` + `/models`, `Authorization: Bearer` auth.
    case openAICompatible
    /// Anthropic `/v1/messages` + `/v1/models`, `x-api-key` + `anthropic-version`.
    case anthropic
}

// MARK: - AI Provider

/// The AI provider to use for AI-powered features.
enum AIProvider: String, CaseIterable, Identifiable, Codable {
    case appleIntelligence = "apple"
    case ollama = "ollama"
    case openAI = "openai"
    case anthropic = "anthropic"
    case deepseek = "deepseek"
    case doubao = "doubao"
    case qwen = "qwen"
    case kimi = "kimi"
    case zhipu = "zhipu"
    case minimax = "minimax"
    /// Quotio — a local OpenAI-compatible proxy (CLI Proxy API Server) that
    /// fronts many model backends behind one endpoint. Default base URL
    /// http://localhost:8320/v1; live model list pulled from GET /v1/models.
    case quotio = "quotio"

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .appleIntelligence: return "Apple Intelligence"
        case .ollama: return "Ollama (Local)"
        case .openAI: return "OpenAI"
        case .anthropic: return "Claude (Anthropic)"
        case .deepseek: return "DeepSeek"
        case .doubao: return "Doubao 豆包"
        case .qwen: return "Qwen 通义千问"
        case .kimi: return "Kimi 月之暗面"
        case .zhipu: return "Zhipu GLM 智谱"
        case .minimax: return "MiniMax"
        case .quotio: return "Quotio"
        }
    }

    /// One-line explanation shown beneath each provider in the AI settings
    /// pane. These are sentences rather than brand names, and they are handed
    /// to `Text` as an already-built `String`, so only `String(localized:)`
    /// gets them into the string catalog — without it the picker stays English
    /// in the 中文 interface. The brand names stay inside the key because they
    /// are not translated.
    var description: String {
        switch self {
        case .appleIntelligence: return String(localized: "On-device AI powered by Apple's Foundation Models", bundle: .appLanguage)
        case .ollama: return String(localized: "Local AI models running via Ollama server", bundle: .appLanguage)
        case .openAI: return String(localized: "GPT models via the OpenAI API", bundle: .appLanguage)
        case .anthropic: return String(localized: "Claude models via the Anthropic API", bundle: .appLanguage)
        case .deepseek: return String(localized: "DeepSeek chat & reasoning models", bundle: .appLanguage)
        case .doubao: return String(localized: "ByteDance Doubao models via Volcengine Ark", bundle: .appLanguage)
        case .qwen: return String(localized: "Alibaba Qwen models via DashScope", bundle: .appLanguage)
        case .kimi: return String(localized: "Moonshot Kimi models", bundle: .appLanguage)
        case .zhipu: return String(localized: "Zhipu GLM models", bundle: .appLanguage)
        case .minimax: return String(localized: "MiniMax abab models", bundle: .appLanguage)
        case .quotio: return String(localized: "Local OpenAI-compatible proxy routing to many model backends", bundle: .appLanguage)
        }
    }

    /// SF Symbol fallback, used only if the brand asset is unavailable.
    var iconName: String {
        switch self {
        case .appleIntelligence: return "apple.logo"
        case .ollama: return "server.rack"
        case .openAI: return "sparkles"
        case .anthropic: return "a.circle"
        case .deepseek: return "magnifyingglass.circle"
        case .doubao: return "cloud"
        case .qwen: return "cloud.sun"
        case .kimi: return "moon.stars"
        case .zhipu: return "brain"
        case .minimax: return "bolt.horizontal.circle"
        case .quotio: return "point.3.connected.trianglepath.dotted"
        }
    }

    /// Name of the brand image in `Assets.xcassets` (vector SVG). Render via
    /// the shared `ProviderIcon` view, which falls back to `iconName` when the
    /// asset is missing.
    var brandAssetName: String { "brand-\(rawValue)" }

    /// Whether the brand asset is a single-color glyph that should be tinted to
    /// the surrounding foreground color (so it adapts to light/dark mode).
    /// Full-color brand marks render in their original colors instead.
    var brandAssetIsMonochrome: Bool {
        switch self {
        case .appleIntelligence, .openAI, .ollama: return true
        default: return false
        }
    }

    /// Whether this provider is a remote cloud API requiring an API key.
    var isCloud: Bool {
        switch self {
        case .appleIntelligence, .ollama: return false
        default: return true
        }
    }

    /// Whether this provider can accept image input for vision-based tasks.
    var supportsVision: Bool {
        switch self {
        case .openAI, .anthropic, .doubao, .qwen, .kimi, .zhipu: return true
        // Quotio can route to vision models, but reliability depends on which
        // backends the user's proxy has configured, so don't auto-route image
        // tasks to it; users can still pick a vision model manually.
        case .appleIntelligence, .ollama, .deepseek, .minimax, .quotio: return false
        }
    }

    /// Whether the provider serves OpenAI's `POST /audio/transcriptions`
    /// multipart speech-to-text route at its configured base URL.
    ///
    /// These are the gateways documented to expose that route; because the
    /// base URL and model are both user-editable, anyone running another
    /// OpenAI-compatible ASR endpoint can reach it through Quotio. A provider
    /// that turns out not to serve the route answers with its own HTTP error,
    /// which is surfaced verbatim rather than hidden.
    var supportsAudioTranscription: Bool {
        switch self {
        case .openAI, .qwen, .quotio: return true
        case .anthropic, .deepseek, .doubao, .zhipu, .minimax, .kimi,
             .appleIntelligence, .ollama: return false
        }
    }

    /// Curated speech-to-text model IDs. Editable in the audio pane, since
    /// availability varies by account and region.
    var defaultTranscriptionModels: [String] {
        switch self {
        case .openAI: return ["gpt-4o-transcribe", "gpt-4o-mini-transcribe", "whisper-1"]
        case .qwen: return ["qwen3-asr-flash", "qwen-audio-asr"]
        case .quotio: return ["whisper-1"]
        default: return []
        }
    }

    /// Speech-to-text path appended to the base URL.
    var transcriptionPath: String { "/audio/transcriptions" }

    /// Whether the OpenAI-style `response_format: {type: json_object}` is
    /// supported. Providers without it still receive the JSON schema in the
    /// prompt and are parsed with tolerant extraction.
    var supportsJSONResponseFormat: Bool {
        switch self {
        case .openAI, .deepseek, .qwen: return true
        // Kimi's coding-plan endpoint rejects the `response_format` field
        // (returns 401), so JSON is requested via the prompt + tolerant parsing.
        // Quotio fronts many backends (not all support response_format), so
        // request JSON via the prompt + tolerant parsing instead.
        case .anthropic, .doubao, .zhipu, .minimax, .kimi, .appleIntelligence, .ollama, .quotio: return false
        }
    }

    // MARK: Cloud REST metadata (only meaningful when `isCloud`)

    var apiStyle: AIProviderAPIStyle {
        switch self {
        case .anthropic: return .anthropic
        default: return .openAICompatible
        }
    }

    /// Default base URL (without a trailing slash). Paths below are appended.
    ///
    /// Cloud providers default to their mainland-China (domestic) endpoints;
    /// users outside China can override with the international host in Settings
    /// (e.g. Qwen → dashscope-intl…, MiniMax → api.minimax.io, GLM → api.z.ai).
    var defaultBaseURL: String {
        switch self {
        case .openAI: return "https://api.openai.com/v1"
        case .anthropic: return "https://api.anthropic.com"
        case .deepseek: return "https://api.deepseek.com/v1"
        case .doubao: return "https://ark.cn-beijing.volces.com/api/v3"
        // Mainland-China DashScope (百炼). International users override with
        // https://dashscope-intl.aliyuncs.com/compatible-mode/v1
        case .qwen: return "https://dashscope.aliyuncs.com/compatible-mode/v1"
        // Kimi coding-plan endpoint (OpenAI-compatible). For the Anthropic
        // format set the base to https://api.kimi.com/coding and API Format
        // to Anthropic (path becomes …/coding/v1/messages).
        case .kimi: return "https://api.kimi.com/coding/v1"
        case .zhipu: return "https://open.bigmodel.cn/api/paas/v4"
        // MiniMax mainland-China host. International users override with
        // https://api.minimax.io/v1
        case .minimax: return "https://api.minimaxi.com/v1"
        // Local CLI Proxy API Server. Override the host/port in Settings if the
        // proxy runs elsewhere.
        case .quotio: return "http://localhost:8320/v1"
        case .appleIntelligence, .ollama: return ""
        }
    }

    /// Chat-completion path appended to the base URL.
    var chatPath: String {
        switch self {
        case .anthropic: return "/v1/messages"
        default: return "/chat/completions"
        }
    }

    /// Model-list path appended to the base URL, or `nil` when the provider
    /// has no standard listing endpoint (defaults are used instead).
    /// Every cloud provider here exposes an OpenAI-style `GET /models` (or the
    /// Anthropic `/v1/models`), so model lists are pulled live rather than
    /// relying on the curated `defaultModels` fallbacks.
    var modelsPath: String? {
        switch self {
        case .anthropic: return "/v1/models"
        // Kimi's coding endpoint does expose `GET /coding/v1/models` (returns the
        // single `kimi-for-coding` / "K2.7 Code" model), so live listing works.
        case .openAI, .deepseek, .qwen, .doubao, .zhipu, .minimax, .quotio, .kimi: return "/models"
        case .appleIntelligence, .ollama: return nil
        }
    }

    /// Curated fallback model IDs shown when live listing is unavailable.
    /// These are only a starting hint — use "Refresh Models" to pull the
    /// provider's current list from its API.
    var defaultModels: [String] {
        switch self {
        case .openAI:
            return ["gpt-4o", "gpt-4.1", "gpt-4.1-mini", "o4-mini", "o3", "gpt-4o-mini"]
        case .anthropic:
            // Newest first — the first entry doubles as the default selection.
            return ["claude-sonnet-4-6", "claude-opus-4-8", "claude-haiku-4-5", "claude-sonnet-4-5", "claude-opus-4-1"]
        case .deepseek:
            return ["deepseek-chat", "deepseek-reasoner"]
        case .doubao:
            // Ark model IDs use dashes + a date suffix (NOT dots), and must be
            // activated in the Ark Console (or use an inference endpoint ID, ep-…).
            return ["doubao-seed-1-6-250615", "doubao-1-5-pro-32k-250115", "doubao-1-5-vision-pro-32k-250115", "doubao-seed-1-6-flash-250828", "doubao-1-5-lite-32k-250115"]
        case .qwen:
            return ["qwen-plus", "qwen-max", "qwen-turbo", "qwen-vl-max", "qwen-vl-plus", "qwen-max-latest"]
        case .kimi:
            // The coding endpoint (api.kimi.com/coding/v1) serves the K2.7 model
            // under the id `kimi-for-coding`; `kimi-k2.7` also resolves to it.
            // Both are thinking-only (temperature must be 1, omitted by the
            // client). Moonshot Open Platform users can override the Base URL and
            // type a kimi-latest / kimi-k2.x id instead.
            return ["kimi-for-coding", "kimi-k2.7"]
        case .zhipu:
            return ["glm-4.6", "glm-4.5", "glm-4-plus", "glm-4.5v", "glm-4v-plus", "glm-4-flash"]
        case .minimax:
            return ["MiniMax-M2.5", "MiniMax-M2.7", "MiniMax-M3", "MiniMax-Text-01"]
        case .quotio:
            // Starter hints only — Quotio exposes its live catalog via
            // GET /v1/models, so use "Refresh Models" to pull what the running
            // proxy actually serves. First entry doubles as the default.
            return ["gpt-5-mini", "gpt-5", "claude-sonnet-4-6", "deepseek-v3.2-chat", "qwen3-max-preview", "glm-4.6", "gemini-3.5-flash-low"]
        case .appleIntelligence, .ollama:
            return []
        }
    }

    /// A known vision-capable model id for this provider, used when an image
    /// task (grading, photo cleanup) needs vision but the user's selected model
    /// is text-only.
    var defaultVisionModel: String? {
        switch self {
        case .openAI: return "gpt-4o"
        case .anthropic: return "claude-sonnet-4-6"
        case .qwen: return "qwen-vl-max"
        case .doubao: return "doubao-1-5-vision-pro-32k-250115"
        case .zhipu: return "glm-4.5v"
        case .kimi: return "kimi-for-coding"
        case .deepseek, .minimax, .appleIntelligence, .ollama, .quotio: return nil
        }
    }

    /// Keychain account name for this provider's API key.
    var keychainAccount: String { "apikey.\(rawValue)" }

    /// URL to obtain an API key, for the settings help link.
    var apiKeyURL: String? {
        switch self {
        case .openAI: return "https://platform.openai.com/api-keys"
        case .anthropic: return "https://console.anthropic.com/settings/keys"
        case .deepseek: return "https://platform.deepseek.com/api_keys"
        case .doubao: return "https://console.volcengine.com/ark"
        case .qwen: return "https://dashscope.console.aliyun.com/apiKey"
        // Kimi *Code* console — the coding-plan key. NOT the Moonshot Open
        // Platform (platform.kimi.ai); their keys are not interchangeable.
        case .kimi: return "https://www.kimi.com/code/console"
        case .zhipu: return "https://open.bigmodel.cn/usercenter/apikeys"
        case .minimax: return "https://platform.minimaxi.com/user-center/basic-information/interface-key"
        case .quotio: return "https://www.quotio.dev/docs"
        case .appleIntelligence, .ollama: return nil
        }
    }
}

// MARK: - AI Model Settings

/// Observable settings for AI model configuration.
@Observable
@MainActor
final class AIModelSettings {

    static let shared = AIModelSettings()

    // MARK: - UserDefaults Keys

    private enum Keys {
        static let provider = "ai_provider"
        static let ollamaModel = "ollama_model"
        static let ollamaHost = "ollama_host"
        static let enableThinking = "ollama_enable_thinking"
        static let contextLength = "ollama_context_length"
        static let cloudModels = "cloud_model_selections"   // [providerRaw: modelID]
        static let cloudBaseURLs = "cloud_base_overrides"   // [providerRaw: baseURL]
        static let cloudAPIStyles = "cloud_api_style_overrides" // [providerRaw: "openai"|"anthropic"]
        static let aiPhotoCleanup = "ai_photo_cleanup_enabled"
        static let batchConcurrency = "ai_batch_concurrency"
        static let transcriptionEngine = "ai_transcription_engine"
        static let transcriptionModels = "ai_transcription_models"  // [providerRaw: modelID]
    }

    /// Allowed range for batch-analysis parallelism. Capped low enough that a
    /// cloud provider's rate limits aren't trivially tripped, but high enough
    /// to meaningfully speed up large lists.
    static let batchConcurrencyRange = 1...10

    // MARK: - Properties

    /// The currently selected AI provider.
    var provider: AIProvider {
        didSet { UserDefaults.standard.set(provider.rawValue, forKey: Keys.provider) }
    }

    /// The selected Ollama model name.
    var ollamaModel: String {
        didSet { UserDefaults.standard.set(ollamaModel, forKey: Keys.ollamaModel) }
    }

    /// The Ollama server host URL.
    var ollamaHost: String {
        didSet {
            UserDefaults.standard.set(ollamaHost, forKey: Keys.ollamaHost)
            updateOllamaServiceHost()
        }
    }

    /// Whether to enable thinking/reasoning mode for Ollama models.
    var enableThinking: Bool {
        didSet { UserDefaults.standard.set(enableThinking, forKey: Keys.enableThinking) }
    }

    /// Context length for Ollama models (in tokens).
    var contextLength: Int {
        didSet { UserDefaults.standard.set(contextLength, forKey: Keys.contextLength) }
    }

    /// When enabled, uploaded photos are passed through the selected AI
    /// provider for OCR cleanup/structuring before downstream processing.
    var aiPhotoCleanupEnabled: Bool {
        didSet { UserDefaults.standard.set(aiPhotoCleanupEnabled, forKey: Keys.aiPhotoCleanup) }
    }

    /// How many words the batch AI word-analysis processes in parallel. Clamped
    /// to `batchConcurrencyRange` on write so a corrupted/out-of-range value can
    /// never reach the task group.
    var batchConcurrency: Int {
        didSet {
            let clamped = min(max(batchConcurrency, Self.batchConcurrencyRange.lowerBound),
                              Self.batchConcurrencyRange.upperBound)
            if clamped != batchConcurrency {
                batchConcurrency = clamped
                return  // the re-assignment re-enters didSet and persists the clamped value
            }
            UserDefaults.standard.set(batchConcurrency, forKey: Keys.batchConcurrency)
        }
    }

    /// Which engine transcribes recorded and imported audio.
    var transcriptionEngine: AudioTranscriptionEngine {
        didSet { UserDefaults.standard.set(transcriptionEngine.rawValue, forKey: Keys.transcriptionEngine) }
    }

    /// Per-provider selected speech-to-text model IDs.
    private(set) var transcriptionModelSelections: [String: String] {
        didSet { persistDictionary(transcriptionModelSelections, key: Keys.transcriptionModels) }
    }

    /// Per-provider selected cloud model IDs.
    private(set) var cloudModelSelections: [String: String] {
        didSet { persistDictionary(cloudModelSelections, key: Keys.cloudModels) }
    }

    /// Per-provider base URL overrides (empty entry → use provider default).
    private(set) var cloudBaseURLOverrides: [String: String] {
        didSet { persistDictionary(cloudBaseURLOverrides, key: Keys.cloudBaseURLs) }
    }

    /// Per-provider API-format overrides ("openai" / "anthropic"). When absent,
    /// the provider's built-in style is used. Lets users point a provider at an
    /// Anthropic-compatible gateway (e.g. a Kimi "coding" endpoint).
    private(set) var apiStyleOverrides: [String: String] {
        didSet { persistDictionary(apiStyleOverrides, key: Keys.cloudAPIStyles) }
    }

    /// In-memory mirror of Keychain API keys so SwiftUI reacts to changes.
    /// Loaded from the Keychain at init; writes go through to the Keychain.
    private(set) var apiKeys: [String: String] = [:]

    // MARK: - Initialization

    private init() {
        let savedProvider = UserDefaults.standard.string(forKey: Keys.provider) ?? AIProvider.appleIntelligence.rawValue
        self.provider = AIProvider(rawValue: savedProvider) ?? .appleIntelligence

        self.ollamaModel = UserDefaults.standard.string(forKey: Keys.ollamaModel) ?? "gpt-oss:20b"
        self.ollamaHost = UserDefaults.standard.string(forKey: Keys.ollamaHost) ?? "http://localhost:11434"
        self.enableThinking = UserDefaults.standard.object(forKey: Keys.enableThinking) as? Bool ?? true
        self.contextLength = UserDefaults.standard.object(forKey: Keys.contextLength) as? Int ?? 128000
        self.aiPhotoCleanupEnabled = UserDefaults.standard.object(forKey: Keys.aiPhotoCleanup) as? Bool ?? false

        // Default 3 — a safe parallelism that speeds up large lists without
        // tripping typical cloud rate limits. Clamp the persisted value in case
        // it was written by a future build with a wider range. (didSet does not
        // fire for this in-init assignment, so clamp here explicitly.)
        let savedConcurrency = UserDefaults.standard.object(forKey: Keys.batchConcurrency) as? Int ?? 3
        self.batchConcurrency = min(max(savedConcurrency, AIModelSettings.batchConcurrencyRange.lowerBound),
                                    AIModelSettings.batchConcurrencyRange.upperBound)

        // Apple Speech stays the default: it is free, needs no key, and keeps
        // the audio on device whenever the locale's model is installed.
        let savedEngine = UserDefaults.standard.string(forKey: Keys.transcriptionEngine) ?? ""
        self.transcriptionEngine = AudioTranscriptionEngine(rawValue: savedEngine) ?? .appleSpeech

        self.cloudModelSelections = AIModelSettings.loadDictionary(key: Keys.cloudModels)
        self.transcriptionModelSelections = AIModelSettings.loadDictionary(key: Keys.transcriptionModels)
        self.cloudBaseURLOverrides = AIModelSettings.loadDictionary(key: Keys.cloudBaseURLs)
        self.apiStyleOverrides = AIModelSettings.loadDictionary(key: Keys.cloudAPIStyles)

        // Load API keys from Keychain into the observable mirror.
        var keys: [String: String] = [:]
        for p in AIProvider.allCases where p.isCloud {
            if let value = KeychainHelper.get(account: p.keychainAccount), !value.isEmpty {
                keys[p.rawValue] = value
            }
        }
        self.apiKeys = keys

        updateOllamaServiceHost()
    }

    // MARK: - Per-Provider Accessors

    /// The API key for a cloud provider (empty string when none).
    func apiKey(for provider: AIProvider) -> String {
        apiKeys[provider.rawValue] ?? ""
    }

    /// Store or clear a cloud provider's API key (Keychain + observable mirror).
    func setAPIKey(_ value: String, for provider: AIProvider) {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        let previous = apiKeys[provider.rawValue] ?? ""
        KeychainHelper.set(trimmed, account: provider.keychainAccount)
        if trimmed.isEmpty {
            apiKeys.removeValue(forKey: provider.rawValue)
        } else {
            apiKeys[provider.rawValue] = trimmed
        }
        if provider == .minimax, previous != trimmed {
            // MiniMax text and AI Audio intentionally share one Keychain key.
            // Invalidate credential-scoped live voice metadata regardless of
            // which Settings surface changed that shared credential.
            MiniMaxAudioCatalogStore.shared.activateSharedCredential(apiKey: trimmed)
            AppPreferences.shared.invalidateCredentialScopedVoiceProvenance()
            BatchExplanationController.shared.cancel()
        }
    }

    /// The effective base URL for a cloud provider (override or default).
    func baseURL(for provider: AIProvider) -> String {
        let override = cloudBaseURLOverrides[provider.rawValue]?.trimmingCharacters(in: .whitespacesAndNewlines)
        if let override, !override.isEmpty { return override }
        return provider.defaultBaseURL
    }

    func setBaseURLOverride(_ value: String, for provider: AIProvider) {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty || trimmed == provider.defaultBaseURL {
            cloudBaseURLOverrides.removeValue(forKey: provider.rawValue)
        } else {
            cloudBaseURLOverrides[provider.rawValue] = trimmed
        }
    }

    /// The API-format override for a provider, or nil when using its default.
    func apiStyleOverride(for provider: AIProvider) -> AIProviderAPIStyle? {
        switch apiStyleOverrides[provider.rawValue] {
        case "anthropic": return .anthropic
        case "openai": return .openAICompatible
        default: return nil
        }
    }

    func setAPIStyleOverride(_ style: AIProviderAPIStyle?, for provider: AIProvider) {
        switch style {
        case .anthropic: apiStyleOverrides[provider.rawValue] = "anthropic"
        case .openAICompatible: apiStyleOverrides[provider.rawValue] = "openai"
        case nil: apiStyleOverrides.removeValue(forKey: provider.rawValue)
        }
    }

    /// The effective API style for a provider (override or built-in default).
    func effectiveAPIStyle(for provider: AIProvider) -> AIProviderAPIStyle {
        apiStyleOverride(for: provider) ?? provider.apiStyle
    }

    /// Chat path derived from the effective API style.
    func effectiveChatPath(for provider: AIProvider) -> String {
        switch effectiveAPIStyle(for: provider) {
        case .anthropic: return "/v1/messages"
        case .openAICompatible: return "/chat/completions"
        }
    }

    /// Models-list path derived from the effective API style.
    func effectiveModelsPath(for provider: AIProvider) -> String? {
        switch effectiveAPIStyle(for: provider) {
        case .anthropic: return "/v1/models"
        case .openAICompatible: return provider.modelsPath
        }
    }

    /// Heuristic: does this model id look vision-capable (accepts images)?
    static func isLikelyVisionModel(_ id: String) -> Bool {
        let l = id.lowercased()
        if ["vl", "vision", "omni", "qvq", "4v", "glm-4.5v", "pixtral", "llava", "internvl", "minicpm-v", "gemini"]
            .contains(where: { l.contains($0) }) { return true }
        // Providers whose flagship chat models are multimodal.
        if l.hasPrefix("claude-") || l.contains("gpt-4o") || l.contains("gpt-4.1") || l.hasPrefix("o4") || l.hasPrefix("o3") { return true }
        // Doubao multimodal "seed"/vision families.
        if l.contains("seed-1-6") || l.contains("seed-1-8") || l.contains("seed-2-") || l.contains("1-5-vision") { return true }
        return false
    }

    /// Resolve a vision-capable model for image tasks: the user's selected model
    /// if it's vision-capable, otherwise a vision model from the live list, then
    /// the provider's curated default vision model.
    func visionModel(for provider: AIProvider) -> String? {
        let selected = selectedModel(for: provider)
        // Respect the user's selection if it's already a vision model.
        if Self.isLikelyVisionModel(selected) { return selected }
        // Otherwise prefer the provider's known-good vision model.
        if let curated = provider.defaultVisionModel { return curated }
        // Last resort: any vision-looking model from the live list.
        return CloudAIService.shared.models(for: provider).map(\.id).first(where: Self.isLikelyVisionModel)
    }

    /// The selected model for a provider. Ollama maps to `ollamaModel`;
    /// cloud providers use their per-provider selection (or first default).
    func selectedModel(for provider: AIProvider) -> String {
        switch provider {
        case .ollama:
            return ollamaModel
        case .appleIntelligence:
            return ""
        default:
            if let chosen = cloudModelSelections[provider.rawValue], !chosen.isEmpty {
                return chosen
            }
            return provider.defaultModels.first ?? ""
        }
    }

    func setSelectedModel(_ model: String, for provider: AIProvider) {
        switch provider {
        case .ollama:
            ollamaModel = model
        case .appleIntelligence:
            break
        default:
            cloudModelSelections[provider.rawValue] = model
        }
    }

    // MARK: - Audio Transcription

    /// The provider that will serve an AI transcription request: the effective
    /// provider when it can do speech-to-text, otherwise the first configured
    /// one that can. Returns `nil` when no configured provider offers it.
    func transcriptionProvider() -> AIProvider? {
        let effective = effectiveProvider
        if effective.supportsAudioTranscription, isAvailable(effective) { return effective }
        return AIProvider.allCases.first { $0.supportsAudioTranscription && isAvailable($0) }
    }

    /// Whether AI transcription can run right now.
    var isAITranscriptionAvailable: Bool { transcriptionProvider() != nil }

    /// The selected speech-to-text model for a provider, falling back to its
    /// first curated default.
    func transcriptionModel(for provider: AIProvider) -> String {
        if let chosen = transcriptionModelSelections[provider.rawValue], !chosen.isEmpty {
            return chosen
        }
        return provider.defaultTranscriptionModels.first ?? ""
    }

    func setTranscriptionModel(_ model: String, for provider: AIProvider) {
        let trimmed = model.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty {
            transcriptionModelSelections.removeValue(forKey: provider.rawValue)
        } else {
            transcriptionModelSelections[provider.rawValue] = trimmed
        }
    }

    // MARK: - Availability

    /// Whether Apple Intelligence is available.
    var isAppleIntelligenceAvailable: Bool {
        #if canImport(FoundationModels)
        return AIWordExplanationService.shared.isAvailable
        #else
        return false
        #endif
    }

    /// Whether a given provider is usable right now.
    func isAvailable(_ provider: AIProvider) -> Bool {
        switch provider {
        case .appleIntelligence:
            return isAppleIntelligenceAvailable
        case .ollama:
            return OllamaService.shared.isConnected
        default:
            return !apiKey(for: provider).isEmpty
        }
    }

    /// Whether any provider is available for AI features.
    var isAnyProviderAvailable: Bool {
        AIProvider.allCases.contains { isAvailable($0) }
    }

    /// Current effective provider — the selected one if usable, otherwise the
    /// first available provider, otherwise the selected one (so errors surface).
    var effectiveProvider: AIProvider {
        if isAvailable(provider) { return provider }
        return AIProvider.allCases.first { isAvailable($0) } ?? provider
    }

    /// Whether Ollama is selected and available.
    var isOllamaActive: Bool {
        provider == .ollama && OllamaService.shared.isConnected
    }

    /// Status message for the current configuration.
    ///
    /// The settings pane renders this as an already-built `String`, so nothing
    /// here is extracted by Xcode unless it goes through `String(localized:)`;
    /// left as plain literals the AI status line reports in English even when
    /// the rest of the 中文 interface is translated. Model names and provider
    /// brand names are substituted as `%@` so they stay verbatim while the
    /// sentence around them can be reordered by a translation.
    var statusMessage: String {
        switch provider {
        case .appleIntelligence:
            return isAppleIntelligenceAvailable
                ? String(localized: "Apple Intelligence is ready", bundle: .appLanguage)
                : (AIWordExplanationService.shared.unavailabilityReason
                    ?? String(localized: "Apple Intelligence is not available", bundle: .appLanguage))
        case .ollama:
            if OllamaService.shared.isConnected {
                return ollamaModel.isEmpty
                    ? String(localized: "Connected — select a model", bundle: .appLanguage)
                    : String(format: String(localized: "Connected to %@", bundle: .appLanguage), ollamaModel)
            }
            return OllamaService.shared.connectionError ?? String(localized: "Not connected to Ollama", bundle: .appLanguage)
        default:
            if apiKey(for: provider).isEmpty {
                return String(format: String(localized: "Add your %@ API key", bundle: .appLanguage), provider.displayName)
            }
            let model = selectedModel(for: provider)
            return model.isEmpty
                ? String(localized: "Ready — select a model", bundle: .appLanguage)
                : String(format: String(localized: "Using %@", bundle: .appLanguage), model)
        }
    }

    /// Options dictionary for Ollama requests based on current settings.
    var ollamaOptions: [String: Ollama.Value] {
        [
            "num_ctx": .int(contextLength),
            "temperature": .double(0.7),
            "top_p": .double(0.9),
            "repeat_penalty": .double(1.1),
            "num_predict": .int(-1),
        ]
    }

    // MARK: - Methods

    private func updateOllamaServiceHost() {
        if let url = URL(string: ollamaHost) {
            OllamaService.shared.hostURL = url
        }
    }

    /// Refresh connection and available models for the active provider.
    func refreshConnection() async {
        switch provider {
        case .ollama:
            await OllamaService.shared.checkConnection()
            if OllamaService.shared.isConnected {
                await OllamaService.shared.refreshModels()
            }
        default:
            if provider.isCloud {
                await CloudAIService.shared.refreshModels(for: provider)
            }
        }
    }

    /// Select the first available Ollama model if none is selected.
    func selectDefaultModelIfNeeded() {
        if ollamaModel.isEmpty, let firstModel = OllamaService.shared.availableModels.first {
            ollamaModel = firstModel.name
        }
    }

    /// Reset to default settings.
    func resetToDefaults() {
        provider = .appleIntelligence
        ollamaModel = "gpt-oss:20b"
        ollamaHost = "http://localhost:11434"
        enableThinking = true
        contextLength = 128000
        aiPhotoCleanupEnabled = false
    }

    // MARK: - Persistence Helpers

    private func persistDictionary(_ dict: [String: String], key: String) {
        if let data = try? JSONEncoder().encode(dict) {
            UserDefaults.standard.set(data, forKey: key)
        }
    }

    private static func loadDictionary(key: String) -> [String: String] {
        guard let data = UserDefaults.standard.data(forKey: key),
              let dict = try? JSONDecoder().decode([String: String].self, from: data) else {
            return [:]
        }
        return dict
    }
}

