"""Round-trip writer for Xcode's .xcstrings formatting.

Reproduces Xcode's exact serialization so hand-added keys land as a minimal
diff instead of reformatting the whole catalog.
"""
import collections
import json


def load(path):
    with open(path, encoding="utf-8") as f:
        return json.load(f, object_pairs_hook=collections.OrderedDict)


def _dump(value, pad):
    if isinstance(value, dict):
        if not value:
            return "{\n\n" + pad + "}"
        inner = pad + "  "
        lines = [
            inner + json.dumps(k, ensure_ascii=False) + " : " + _dump(v, inner)
            for k, v in value.items()
        ]
        return "{\n" + ",\n".join(lines) + "\n" + pad + "}"
    if isinstance(value, list):
        if not value:
            return "[\n\n" + pad + "]"
        inner = pad + "  "
        lines = [inner + _dump(v, inner) for v in value]
        return "[\n" + ",\n".join(lines) + "\n" + pad + "]"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if value is None:
        return "null"
    if isinstance(value, (int, float)):
        return json.dumps(value)
    return json.dumps(value, ensure_ascii=False)


def dumps(doc):
    return _dump(doc, "")


def translated(value):
    return collections.OrderedDict(
        [
            (
                "localizations",
                collections.OrderedDict(
                    [
                        (
                            "zh-Hans",
                            collections.OrderedDict(
                                [
                                    (
                                        "stringUnit",
                                        collections.OrderedDict(
                                            [("state", "translated"), ("value", value)]
                                        ),
                                    )
                                ]
                            ),
                        )
                    ]
                ),
            )
        ]
    )


def insert(strings, key, entry):
    """Insert `key` near its alphabetical neighbours, preserving existing order."""
    if key in strings:
        return False
    items = list(strings.items())
    fold = key.casefold()
    position = len(items)
    for index, (existing, _) in enumerate(items):
        if existing.casefold() > fold:
            position = index
            break
    items.insert(position, (key, entry))
    strings.clear()
    strings.update(items)
    return True

