//
//  AudioTranscriptionService.swift
//  SwiftMandarin
//
//  One-shot transcription for recorded or imported audio files. This uses the
//  Apple Speech URL recognizer and prefers on-device recognition whenever the
//  selected locale supports it.
//

import Foundation
@preconcurrency import Speech

/// Which engine turns a recorded or imported clip into text.
///
/// Apple Speech is the default: free, no key, and on-device whenever the
/// locale's dictation model is installed. The AI provider is the answer when
/// that model is missing or the recording defeats it — at the cost of sending
/// the audio to the configured provider, which is why it is an explicit choice.
nonisolated enum AudioTranscriptionEngine: String, CaseIterable, Identifiable, Sendable {
    case appleSpeech
    case aiProvider

    var id: String { rawValue }
}

nonisolated enum AudioTranscriptionError: LocalizedError {
    case notAuthorized
    case restricted
    case recognizerUnavailable(language: String)
    case emptyTranscript
    case recognitionFailed(String)
    case timedOut
    case noTranscriptionProvider

    var errorDescription: String? {
        switch self {
        case .notAuthorized:
            #if os(iOS)
            return String(localized: "Speech recognition access is required to transcribe audio. Enable it in Settings and try again.", bundle: .appLanguage)
            #else
            return String(localized: "Speech recognition access is required to transcribe audio. Enable it in System Settings and try again.", bundle: .appLanguage)
            #endif
        case .restricted:
            return String(localized: "Speech recognition is restricted on this device.", bundle: .appLanguage)
        case .recognizerUnavailable(let language):
            return String.localizedStringWithFormat(
                String(localized: "Apple Speech has no recognizer available for %@. Turn on Dictation in Settings (which downloads the language), check your network connection, or switch to an AI transcription provider.", bundle: .appLanguage),
                language
            )
        case .emptyTranscript:
            return String(localized: "Apple Speech could not find spoken words in this audio. Check the recognition language and audio quality, then try again.", bundle: .appLanguage)
        case .recognitionFailed(let message):
            return String(localized: "Audio transcription failed:", bundle: .appLanguage) + " " + message
        case .timedOut:
            return String(localized: "Apple Speech stopped responding before it finished this audio. Try a shorter clip, or switch to an AI transcription provider.", bundle: .appLanguage)
        case .noTranscriptionProvider:
            return String(localized: "AI transcription needs a provider with a speech-to-text endpoint (OpenAI, Qwen, or Quotio). Add an API key in Settings → AI, or switch back to Apple Speech.", bundle: .appLanguage)
        }
    }
}

extension SpeechRecognitionLanguage {
    /// ISO-639-1 hint for a speech-to-text API. Both Chinese variants map to
    /// `zh`; script selection is the model's job, not a language hint's.
    var transcriptionLanguageCode: String {
        switch self {
        case .english: return "en"
        case .chinese, .chineseTraditional: return "zh"
        }
    }
}

/// A lock-protected, exactly-once bridge for the callback-based Speech API.
/// It also remembers cancellation that arrives before a continuation is
/// installed, which avoids leaving a cancelled task suspended indefinitely.
nonisolated private final class AudioRecognitionGate: @unchecked Sendable {
    private let lock = NSLock()
    private var continuation: CheckedContinuation<String, Error>?
    private var completion: Result<String, Error>?

    func install(_ continuation: CheckedContinuation<String, Error>) {
        let pending: Result<String, Error>?
        lock.lock()
        if let completion {
            pending = completion
        } else {
            self.continuation = continuation
            pending = nil
        }
        lock.unlock()

        if let pending {
            continuation.resume(with: pending)
        }
    }

    func succeed(_ transcript: String) {
        resolve(.success(transcript))
    }

    func fail(_ error: Error) {
        resolve(.failure(error))
    }

    func cancel() {
        resolve(.failure(CancellationError()))
    }

    private func resolve(_ result: Result<String, Error>) {
        let continuation: CheckedContinuation<String, Error>?
        lock.lock()
        guard completion == nil else {
            lock.unlock()
            return
        }
        completion = result
        continuation = self.continuation
        self.continuation = nil
        lock.unlock()

        continuation?.resume(with: result)
    }
}

@MainActor
final class AudioTranscriptionService {
    private var activeTask: SFSpeechRecognitionTask?
    private var activeGate: AudioRecognitionGate?

    /// How long a single recognition pass may run before it is treated as
    /// stalled. Speech can accept a URL request and then never call back — for
    /// an unavailable on-device asset, or when the service drops the request —
    /// which used to leave the UI spinning forever with no way out but Cancel.
    private static let recognitionTimeout: Duration = .seconds(120)

    /// How long to wait for a freshly constructed recognizer to report itself
    /// available. `SFSpeechRecognizer.isAvailable` is false for a short window
    /// after `init` while Speech resolves the locale, so the old immediate
    /// check rejected perfectly good recognizers.
    private static let availabilityTimeout: Duration = .seconds(3)

    /// Transcribe one app-owned audio file with the learner's chosen engine.
    ///
    /// Routing lives here rather than in the view so every audio surface picks
    /// up the same engine preference, and so neither engine can silently
    /// substitute for the other: switching to the AI provider sends the
    /// recording off the device, and that stays an explicit choice.
    func transcribe(
        audioURL: URL,
        language: SpeechRecognitionLanguage,
        engine: AudioTranscriptionEngine
    ) async throws -> String {
        switch engine {
        case .appleSpeech:
            return try await transcribe(audioURL: audioURL, language: language)
        case .aiProvider:
            return try await transcribeWithAI(audioURL: audioURL, language: language)
        }
    }

    /// Transcribe through the configured AI provider's speech-to-text endpoint.
    private func transcribeWithAI(
        audioURL: URL,
        language: SpeechRecognitionLanguage
    ) async throws -> String {
        let settings = AIModelSettings.shared
        guard let provider = settings.transcriptionProvider() else {
            throw AudioTranscriptionError.noTranscriptionProvider
        }
        try Task.checkCancellation()
        let transcript = try await CloudAIService.shared.transcribeAudio(
            provider: provider,
            model: settings.transcriptionModel(for: provider),
            audioURL: audioURL,
            languageCode: language.transcriptionLanguageCode
        )
        // A provider that heard nothing returns an empty or whitespace body;
        // report that the same way Apple Speech does rather than committing a
        // blank transcript to the editor.
        guard !transcript.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            throw AudioTranscriptionError.emptyTranscript
        }
        return transcript
    }

    /// Transcribe one app-owned audio file with Apple Speech.
    ///
    /// On-device recognition is preferred for privacy and offline use, but
    /// `supportsOnDeviceRecognition` only says the *recognizer* can work
    /// offline — it does not promise the locale's assets are installed. When
    /// the on-device pass fails or hears nothing, this retries through Apple's
    /// service rather than reporting a dead end, which is what made
    /// transcription look broken on devices without the Chinese (or any)
    /// dictation model downloaded.
    func transcribe(
        audioURL: URL,
        language: SpeechRecognitionLanguage
    ) async throws -> String {
        try Task.checkCancellation()
        try await ensureAuthorization()
        try Task.checkCancellation()

        guard let recognizer = SFSpeechRecognizer(locale: language.locale) else {
            throw AudioTranscriptionError.recognizerUnavailable(language: language.displayName)
        }
        try await waitUntilAvailable(recognizer, language: language)

        guard recognizer.supportsOnDeviceRecognition else {
            return try await runRecognition(recognizer: recognizer, audioURL: audioURL, onDevice: false)
        }

        do {
            return try await runRecognition(recognizer: recognizer, audioURL: audioURL, onDevice: true)
        } catch let error as AudioTranscriptionError {
            switch error {
            case .recognitionFailed, .emptyTranscript, .timedOut:
                // The on-device model is missing, incomplete, or silent. Apple's
                // service can still read this audio, so try it before failing.
                try Task.checkCancellation()
                return try await runRecognition(recognizer: recognizer, audioURL: audioURL, onDevice: false)
            case .notAuthorized, .restricted, .recognizerUnavailable, .noTranscriptionProvider:
                throw error
            }
        }
    }

    /// Poll until the recognizer reports availability, so a transient false
    /// right after construction is not mistaken for an unusable language.
    private func waitUntilAvailable(
        _ recognizer: SFSpeechRecognizer,
        language: SpeechRecognitionLanguage
    ) async throws {
        guard !recognizer.isAvailable else { return }
        let deadline = ContinuousClock.now.advanced(by: Self.availabilityTimeout)
        while ContinuousClock.now < deadline {
            try await Task.sleep(for: .milliseconds(100))
            if recognizer.isAvailable { return }
        }
        throw AudioTranscriptionError.recognizerUnavailable(language: language.displayName)
    }

    /// One recognition pass over the file, on-device or through Apple's service.
    private func runRecognition(
        recognizer: SFSpeechRecognizer,
        audioURL: URL,
        onDevice: Bool
    ) async throws -> String {
        // Only one URL recognition request should run per service instance.
        cancelActiveRecognition()

        let request = SFSpeechURLRecognitionRequest(url: audioURL)
        request.shouldReportPartialResults = false
        request.taskHint = .dictation
        request.requiresOnDeviceRecognition = onDevice
        // Sentence punctuation makes a transcript usable as editor text and as
        // translation input, instead of one unbroken run of words.
        request.addsPunctuation = true

        let gate = AudioRecognitionGate()
        activeGate = gate

        // The gate resolves exactly once, so this fires only if Speech never
        // does; a late timeout after a successful result is a no-op.
        let timeout = Task {
            try? await Task.sleep(for: Self.recognitionTimeout)
            guard !Task.isCancelled else { return }
            gate.fail(AudioTranscriptionError.timedOut)
        }

        defer {
            timeout.cancel()
            if activeGate === gate {
                // Always stop the underlying recognizer before releasing our
                // only strong reference. In particular, cancellation resolves
                // the continuation immediately; relying on a later main-actor
                // hop would race this defer and could leave Speech processing
                // an abandoned request in the background.
                activeTask?.cancel()
                activeTask = nil
                activeGate = nil
            }
        }

        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                gate.install(continuation)
                guard !Task.isCancelled else {
                    gate.cancel()
                    return
                }

                activeTask = recognizer.recognitionTask(with: request) { result, error in
                    // Speech may deliver a valid final result together with a
                    // stream-end error. A nonempty final transcript is success
                    // and must win over that companion error.
                    if let result, result.isFinal {
                        let transcript = result.bestTranscription.formattedString
                            .trimmingCharacters(in: .whitespacesAndNewlines)
                        if transcript.isEmpty {
                            gate.fail(AudioTranscriptionError.emptyTranscript)
                        } else {
                            gate.succeed(transcript)
                        }
                        return
                    }

                    if let error {
                        gate.fail(AudioTranscriptionError.recognitionFailed(Self.describe(error)))
                    }
                }
            }
        } onCancel: {
            gate.cancel()
        }
    }

    /// Speech errors are famously opaque ("The operation couldn't be
    /// completed"), so keep the domain and code — they are the only way to tell
    /// a missing on-device asset from a network failure.
    private static func describe(_ error: Error) -> String {
        let nsError = error as NSError
        return "\(error.localizedDescription) (\(nsError.domain) \(nsError.code))"
    }

    func cancel() {
        cancelActiveRecognition()
    }

    private func cancelActiveRecognition() {
        activeGate?.cancel()
        activeTask?.cancel()
        activeTask = nil
        activeGate = nil
    }

    private func ensureAuthorization() async throws {
        switch SFSpeechRecognizer.authorizationStatus() {
        case .authorized:
            return
        case .notDetermined:
            let status = await withCheckedContinuation { continuation in
                SFSpeechRecognizer.requestAuthorization { status in
                    continuation.resume(returning: status)
                }
            }
            switch status {
            case .authorized:
                return
            case .restricted:
                throw AudioTranscriptionError.restricted
            case .denied, .notDetermined:
                throw AudioTranscriptionError.notAuthorized
            @unknown default:
                throw AudioTranscriptionError.notAuthorized
            }
        case .denied:
            throw AudioTranscriptionError.notAuthorized
        case .restricted:
            throw AudioTranscriptionError.restricted
        @unknown default:
            throw AudioTranscriptionError.notAuthorized
        }
    }
}

//
//  AudioCaptureService.swift
//  SwiftMandarin
//
//  Records short audio clips for the Multimodal tab and previews app-owned
//  recordings/imports. Source audio remains local and is never sent to
//  MiniMax; transcription is handled separately by Apple's Speech framework.
//

import Foundation
import Observation
import UniformTypeIdentifiers
@preconcurrency import AVFAudio
@preconcurrency import AVFoundation

nonisolated enum AudioCaptureError: LocalizedError {
    case microphoneNotAuthorized
    case recorderCouldNotStart
    case noActiveRecording
    case emptyRecording
    case unsupportedFile
    case fileTooLarge(maximumMegabytes: Int)
    case audioTooLong(maximumSeconds: Int)
    case fileAccessFailed(String)
    case previewFailed(String)

    var errorDescription: String? {
        switch self {
        case .microphoneNotAuthorized:
            #if os(iOS)
            return String(localized: "Microphone access is required to record audio. Enable it in Settings, or import an audio file instead.", bundle: .appLanguage)
            #else
            return String(localized: "Microphone access is required to record audio. Enable it in System Settings, or import an audio file instead.", bundle: .appLanguage)
            #endif
        case .recorderCouldNotStart:
            return String(localized: "The audio recorder could not start. Check that another app is not using the microphone and try again.", bundle: .appLanguage)
        case .noActiveRecording:
            return String(localized: "There is no recording to stop.", bundle: .appLanguage)
        case .emptyRecording:
            return String(localized: "The recording did not contain any audio. Please record again.", bundle: .appLanguage)
        case .unsupportedFile:
            return String(localized: "Choose a playable audio file such as M4A, MP3, WAV, AIFF, or CAF.", bundle: .appLanguage)
        case .fileTooLarge(let maximumMegabytes):
            return String.localizedStringWithFormat(
                String(localized: "This audio file is too large. Choose a file smaller than %lld MB.", bundle: .appLanguage),
                Int64(maximumMegabytes)
            )
        case .audioTooLong(let maximumSeconds):
            return String.localizedStringWithFormat(
                String(localized: "This audio is too long. Choose or record a clip no longer than %lld seconds.", bundle: .appLanguage),
                Int64(maximumSeconds)
            )
        case .fileAccessFailed(let message):
            return String(localized: "The audio file could not be prepared:", bundle: .appLanguage) + " " + message
        case .previewFailed(let message):
            return String(localized: "The audio preview could not start:", bundle: .appLanguage) + " " + message
        }
    }
}

nonisolated enum AudioInputSource: Sendable, Equatable {
    case recording
    case importFile
}

/// Metadata for an app-owned temporary audio file. The original security-
/// scoped import is never retained; `url` always points into the app's temp
/// directory and can therefore be used safely by asynchronous recognition.
nonisolated struct PreparedAudioFile: Identifiable, Equatable, Sendable {
    let id: UUID
    let url: URL
    let displayName: String
    let byteCount: Int64
    let duration: TimeInterval?
    let source: AudioInputSource

    init(
        id: UUID = UUID(),
        url: URL,
        displayName: String,
        byteCount: Int64,
        duration: TimeInterval?,
        source: AudioInputSource
    ) {
        self.id = id
        self.url = url
        self.displayName = displayName
        self.byteCount = byteCount
        self.duration = duration
        self.source = source
    }
}

/// Copies and validates audio selected through a security-scoped file picker.
/// All expensive file work is kept off the main actor.
nonisolated enum AudioInputFileStore {
    static let maximumFileSize = 100 * 1_024 * 1_024
    static let maximumDurationSeconds: TimeInterval = 60

    private static let supportedExtensions: Set<String> = [
        "aac", "aif", "aiff", "caf", "m4a", "mp3", "wav"
    ]

    static func importAudio(from sourceURL: URL) async throws -> PreparedAudioFile {
        let originalName = sourceURL.lastPathComponent.isEmpty
            ? String(localized: "Imported Audio", bundle: .appLanguage)
            : sourceURL.lastPathComponent
        let copiedURL: URL

        do {
            let hasScopedAccess = sourceURL.startAccessingSecurityScopedResource()
            let copyTask = Task.detached(priority: .userInitiated) {
                try copyValidatedAudio(from: sourceURL)
            }
            copiedURL = try await withTaskCancellationHandler {
                defer {
                    if hasScopedAccess {
                        sourceURL.stopAccessingSecurityScopedResource()
                    }
                }
                let url = try await copyTask.value
                do {
                    try Task.checkCancellation()
                } catch {
                    remove(url)
                    throw error
                }
                return url
            } onCancel: {
                copyTask.cancel()
            }
        } catch is CancellationError {
            throw CancellationError()
        } catch let error as AudioCaptureError {
            throw error
        } catch {
            throw AudioCaptureError.fileAccessFailed(error.localizedDescription)
        }

        do {
            return try await inspectOwnedAudio(
                at: copiedURL,
                displayName: originalName,
                source: .importFile
            )
        } catch {
            remove(copiedURL)
            throw error
        }
    }

    static func prepareRecording(at url: URL) async throws -> PreparedAudioFile {
        do {
            return try await inspectOwnedAudio(
                at: url,
                displayName: String(localized: "Recorded Audio.m4a", bundle: .appLanguage),
                source: .recording
            )
        } catch {
            remove(url)
            throw error
        }
    }

    static func remove(_ url: URL) {
        // Every URL accepted here was created in our dedicated temp folder.
        // The containment check prevents an accidental caller from deleting an
        // arbitrary user-selected file.
        let folder = temporaryFolder.standardizedFileURL.path
        let candidate = url.standardizedFileURL.path
        guard candidate.hasPrefix(folder + "/") else { return }
        try? FileManager.default.removeItem(at: url)
    }

    static func removeAllTemporaryFiles() {
        guard let candidates = try? FileManager.default.contentsOfDirectory(
            at: temporaryFolder,
            includingPropertiesForKeys: nil,
            options: [.skipsHiddenFiles]
        ) else { return }
        for candidate in candidates {
            remove(candidate)
        }
    }

    static var temporaryFolder: URL {
        FileManager.default.temporaryDirectory
            .appendingPathComponent("SwiftMandarinAudioInput", isDirectory: true)
    }

    private static func copyValidatedAudio(from sourceURL: URL) throws -> URL {
        let values = try sourceURL.resourceValues(forKeys: [
            .isRegularFileKey,
            .fileSizeKey,
            .contentTypeKey
        ])
        guard values.isRegularFile == true else {
            throw AudioCaptureError.unsupportedFile
        }

        let size = values.fileSize ?? 0
        guard size > 0 else { throw AudioCaptureError.emptyRecording }
        guard size <= maximumFileSize else {
            throw AudioCaptureError.fileTooLarge(maximumMegabytes: maximumFileSize / 1_024 / 1_024)
        }

        let fileExtension = sourceURL.pathExtension.lowercased()
        let declaredType = values.contentType ?? UTType(filenameExtension: fileExtension)
        let isAudioType = declaredType?.conforms(to: .audio) == true
        guard isAudioType || supportedExtensions.contains(fileExtension) else {
            throw AudioCaptureError.unsupportedFile
        }

        let fileManager = FileManager.default
        try fileManager.createDirectory(at: temporaryFolder, withIntermediateDirectories: true)
        let safeExtension = supportedExtensions.contains(fileExtension) ? fileExtension : "audio"
        let destination = temporaryFolder
            .appendingPathComponent(UUID().uuidString)
            .appendingPathExtension(safeExtension)

        guard fileManager.createFile(atPath: destination.path, contents: nil) else {
            throw CocoaError(.fileWriteUnknown)
        }
        do {
            let sourceHandle = try FileHandle(forReadingFrom: sourceURL)
            let destinationHandle = try FileHandle(forWritingTo: destination)
            var copiedByteCount = 0
            defer {
                try? sourceHandle.close()
                try? destinationHandle.close()
            }

            while true {
                try Task.checkCancellation()
                guard let chunk = try sourceHandle.read(upToCount: 1_024 * 1_024),
                      !chunk.isEmpty else { break }
                copiedByteCount += chunk.count
                guard copiedByteCount <= maximumFileSize else {
                    throw AudioCaptureError.fileTooLarge(
                        maximumMegabytes: maximumFileSize / 1_024 / 1_024
                    )
                }
                try destinationHandle.write(contentsOf: chunk)
            }
            try Task.checkCancellation()
            try destinationHandle.synchronize()
        } catch {
            try? fileManager.removeItem(at: destination)
            throw error
        }
        let copiedSize = try destination.resourceValues(forKeys: [.fileSizeKey]).fileSize ?? 0
        guard copiedSize > 0 else {
            try? fileManager.removeItem(at: destination)
            throw AudioCaptureError.emptyRecording
        }
        guard copiedSize <= maximumFileSize else {
            try? fileManager.removeItem(at: destination)
            throw AudioCaptureError.fileTooLarge(maximumMegabytes: maximumFileSize / 1_024 / 1_024)
        }
        return destination
    }

    private static func inspectOwnedAudio(
        at url: URL,
        displayName: String,
        source: AudioInputSource
    ) async throws -> PreparedAudioFile {
        let values = try url.resourceValues(forKeys: [.isRegularFileKey, .fileSizeKey])
        guard values.isRegularFile == true else { throw AudioCaptureError.unsupportedFile }

        let byteCount = Int64(values.fileSize ?? 0)
        guard byteCount > 0 else { throw AudioCaptureError.emptyRecording }
        guard byteCount <= Int64(maximumFileSize) else {
            throw AudioCaptureError.fileTooLarge(maximumMegabytes: maximumFileSize / 1_024 / 1_024)
        }

        let asset = AVURLAsset(url: url)
        guard (try? await asset.load(.isPlayable)) == true else {
            throw AudioCaptureError.unsupportedFile
        }

        guard let loadedDuration = try? await asset.load(.duration) else {
            throw AudioCaptureError.unsupportedFile
        }
        let seconds = CMTimeGetSeconds(loadedDuration)
        guard seconds.isFinite, seconds > 0 else {
            throw AudioCaptureError.emptyRecording
        }
        // A small tolerance avoids rejecting a recorder deadline that lands a
        // fraction of a second late while still honoring Apple Speech's
        // documented one-minute recognition-task boundary.
        guard seconds <= maximumDurationSeconds + 1 else {
            throw AudioCaptureError.audioTooLong(
                maximumSeconds: Int(maximumDurationSeconds)
            )
        }

        return PreparedAudioFile(
            url: url,
            displayName: displayName,
            byteCount: byteCount,
            duration: seconds,
            source: source
        )
    }
}

/// A narrow ownership bridge for the app's single iOS audio session. Source
/// recording/preview and read-aloud are mutually exclusive, and only the
/// engine that currently owns audio activity may deactivate the session.
@MainActor
final class SourceAudioActivityCoordinator {
    static let shared = SourceAudioActivityCoordinator()

    private weak var service: AudioCaptureService?
    #if os(iOS)
    private var interruptionObserver: NSObjectProtocol?
    private var routeChangeObserver: NSObjectProtocol?
    #endif

    var hasActiveSourceAudio: Bool {
        service?.hasActiveAudio == true
    }

    func acquire(_ service: AudioCaptureService) {
        if let existing = self.service, existing !== service {
            existing.stopForExclusiveAudioHandoff()
        }
        self.service = service
    }

    func release(_ service: AudioCaptureService) {
        guard self.service === service else { return }
        self.service = nil
    }

    func stopSourceAudioForSpeech() {
        service?.stopForSpeechPlayback()
    }

    private init() {
        #if os(iOS)
        let center = NotificationCenter.default
        interruptionObserver = center.addObserver(
            forName: AVAudioSession.interruptionNotification,
            object: AVAudioSession.sharedInstance(),
            queue: .main
        ) { [weak self] notification in
            guard let rawValue = notification.userInfo?[AVAudioSessionInterruptionTypeKey] as? UInt,
                  AVAudioSession.InterruptionType(rawValue: rawValue) == .began else { return }
            Task { @MainActor [weak self] in
                await self?.handleAudioSessionLoss(
                    message: String(localized: "Audio was interrupted by another app. Please try again.", bundle: .appLanguage)
                )
            }
        }
        routeChangeObserver = center.addObserver(
            forName: AVAudioSession.routeChangeNotification,
            object: AVAudioSession.sharedInstance(),
            queue: .main
        ) { [weak self] notification in
            guard let rawValue = notification.userInfo?[AVAudioSessionRouteChangeReasonKey] as? UInt,
                  AVAudioSession.RouteChangeReason(rawValue: rawValue) == .oldDeviceUnavailable else { return }
            Task { @MainActor [weak self] in
                await self?.handleAudioSessionLoss(
                    message: String(localized: "Audio stopped because the playback or recording device was disconnected.", bundle: .appLanguage)
                )
            }
        }
        #endif
    }

    private func handleAudioSessionLoss(message: String) async {
        service?.handleAudioSessionLoss(message: message)
        SpeechService.handleAudioSessionLoss(message: message)
        await SpeechRecognitionService.shared.handleAudioSessionLoss(message: message)
    }
}

/// Main-actor recorder/player used by the Multimodal audio input pane.
@MainActor
@Observable
final class AudioCaptureService: NSObject, AVAudioPlayerDelegate {
    private(set) var isRecording = false
    private(set) var isStartingRecording = false
    private(set) var isStartingPlayback = false
    private(set) var playingURL: URL?
    private(set) var completedRecordingURL: URL?
    private(set) var playbackErrorMessage: String?

    private var recorder: AVAudioRecorder?
    private var recordingURL: URL?
    private var player: AVAudioPlayer?
    private var recordingStartID: UUID?
    private var playbackStartID: UUID?
    private var recordingSessionOwner: AudioSessionOwner?
    private var playbackSessionOwner: AudioSessionOwner?

    var hasActiveAudio: Bool {
        isRecording || isStartingRecording || isStartingPlayback
            || recorder != nil || playingURL != nil || player?.isPlaying == true
            || recordingSessionOwner != nil || playbackSessionOwner != nil
    }

    func startRecording() async throws {
        guard !isRecording, !isStartingRecording else { return }
        let requestID = UUID()
        recordingStartID = requestID
        completedRecordingURL = nil
        playbackErrorMessage = nil
        isStartingRecording = true
        defer {
            if recordingStartID == requestID {
                recordingStartID = nil
                isStartingRecording = false
            }
        }

        try Task.checkCancellation()
        guard await requestMicrophonePermissionIfNeeded() else {
            throw AudioCaptureError.microphoneNotAuthorized
        }
        try Task.checkCancellation()
        guard recordingStartID == requestID else { throw CancellationError() }

        stopPlayback()
        await SpeechRecognitionService.shared.stopRecording()
        try Task.checkCancellation()
        guard recordingStartID == requestID else { throw CancellationError() }
        SpeechService.stop()

        let fileManager = FileManager.default
        try fileManager.createDirectory(
            at: AudioInputFileStore.temporaryFolder,
            withIntermediateDirectories: true
        )
        let url = AudioInputFileStore.temporaryFolder
            .appendingPathComponent(UUID().uuidString)
            .appendingPathExtension("m4a")

        let settings: [String: Any] = [
            AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
            AVSampleRateKey: 44_100,
            AVNumberOfChannelsKey: 1,
            AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue,
            AVEncoderBitRateKey: 128_000
        ]
        let sessionOwner = AudioSessionOwner()

        do {
            SourceAudioActivityCoordinator.shared.acquire(self)
            recordingSessionOwner = sessionOwner
            try await AudioSessionCoordinator.shared.acquire(
                .clipRecording,
                owner: sessionOwner
            )
            try Task.checkCancellation()
            guard recordingStartID == requestID,
                  recordingSessionOwner == sessionOwner else {
                AudioSessionCoordinator.shared.release(sessionOwner)
                throw CancellationError()
            }

            let recorder = try AVAudioRecorder(url: url, settings: settings)
            recorder.prepareToRecord()
            guard recorder.record() else {
                throw AudioCaptureError.recorderCouldNotStart
            }
            self.recorder = recorder
            recordingURL = url
            isRecording = true
        } catch {
            AudioSessionCoordinator.shared.release(sessionOwner)
            if recordingSessionOwner == sessionOwner {
                recordingSessionOwner = nil
            }
            AudioInputFileStore.remove(url)
            releaseSessionOwnershipIfIdle()
            if error is CancellationError {
                throw error
            }
            if let captureError = error as? AudioCaptureError {
                throw captureError
            }
            throw AudioCaptureError.fileAccessFailed(error.localizedDescription)
        }
    }

    func stopRecording() throws -> URL {
        guard let recorder, let recordingURL else {
            throw AudioCaptureError.noActiveRecording
        }

        recordingStartID = nil
        isStartingRecording = false
        recorder.stop()
        let sessionOwner = recordingSessionOwner
        recordingSessionOwner = nil
        self.recorder = nil
        self.recordingURL = nil
        isRecording = false
        if let sessionOwner {
            AudioSessionCoordinator.shared.release(sessionOwner)
        }
        releaseSessionOwnershipIfIdle()

        let byteCount = (try? recordingURL.resourceValues(forKeys: [.fileSizeKey]).fileSize) ?? 0
        guard byteCount > 0 else {
            AudioInputFileStore.remove(recordingURL)
            throw AudioCaptureError.emptyRecording
        }
        return recordingURL
    }

    func discardActiveRecording() {
        recordingStartID = nil
        isStartingRecording = false
        let sessionOwner = recordingSessionOwner
        recordingSessionOwner = nil
        recorder?.stop()
        recorder = nil
        isRecording = false
        if let recordingURL {
            AudioInputFileStore.remove(recordingURL)
        }
        recordingURL = nil
        if let sessionOwner {
            AudioSessionCoordinator.shared.release(sessionOwner)
        }
        releaseSessionOwnershipIfIdle()
    }

    func togglePlayback(of url: URL) async throws {
        if playingURL == url || isStartingPlayback {
            stopPlayback()
            return
        }

        stopPlayback()
        let requestID = UUID()
        let sessionOwner = AudioSessionOwner()
        playbackStartID = requestID
        isStartingPlayback = true
        do {
            await SpeechRecognitionService.shared.stopRecording()
            try Task.checkCancellation()
            guard playbackStartID == requestID else { throw CancellationError() }
            SpeechService.stop()
            playbackErrorMessage = nil
            SourceAudioActivityCoordinator.shared.acquire(self)
            let player = try AVAudioPlayer(contentsOf: url)
            player.delegate = self
            guard player.prepareToPlay() else {
                throw AudioCaptureError.previewFailed(
                    String(localized: "The player could not decode this file.", bundle: .appLanguage)
                )
            }

            playbackSessionOwner = sessionOwner
            try await AudioSessionCoordinator.shared.acquire(
                .sourcePreview,
                owner: sessionOwner
            )
            try Task.checkCancellation()
            guard playbackStartID == requestID,
                  playbackSessionOwner == sessionOwner else {
                AudioSessionCoordinator.shared.release(sessionOwner)
                throw CancellationError()
            }

            self.player = player
            playingURL = url
            playbackStartID = nil
            isStartingPlayback = false
            guard player.play() else {
                self.player = nil
                playingURL = nil
                throw AudioCaptureError.previewFailed(
                    String(localized: "The player could not decode this file.", bundle: .appLanguage)
                )
            }
        } catch {
            AudioSessionCoordinator.shared.release(sessionOwner)
            if playbackStartID == requestID {
                playbackStartID = nil
                isStartingPlayback = false
            }
            if playbackSessionOwner == sessionOwner {
                playbackSessionOwner = nil
                player = nil
                playingURL = nil
            }
            releaseSessionOwnershipIfIdle()
            if error is CancellationError {
                throw error
            }
            if let captureError = error as? AudioCaptureError {
                throw captureError
            }
            throw AudioCaptureError.previewFailed(error.localizedDescription)
        }
    }

    func stopPlayback() {
        playbackStartID = nil
        let sessionOwner = playbackSessionOwner
        playbackSessionOwner = nil
        isStartingPlayback = false
        player?.stop()
        player = nil
        playingURL = nil
        if let sessionOwner {
            AudioSessionCoordinator.shared.release(sessionOwner)
        }
        releaseSessionOwnershipIfIdle()
    }

    func stopAll() {
        discardActiveRecording()
        stopPlayback()
        if let completedRecordingURL {
            AudioInputFileStore.remove(completedRecordingURL)
            self.completedRecordingURL = nil
        }
    }

    func stopForSpeechPlayback() {
        if isRecording, let url = try? stopRecording() {
            completedRecordingURL = url
        } else {
            discardActiveRecording()
        }
        stopPlayback()
    }

    func clearPlaybackError() {
        playbackErrorMessage = nil
    }

    func takeCompletedRecordingURL() -> URL? {
        defer { completedRecordingURL = nil }
        return completedRecordingURL
    }

    func audioPlayerDidFinishPlaying(_ player: AVAudioPlayer, successfully flag: Bool) {
        guard player === self.player else { return }
        let sessionOwner = playbackSessionOwner
        playbackSessionOwner = nil
        self.player = nil
        playingURL = nil
        if !flag {
            playbackErrorMessage = String(localized: "The audio preview stopped before it finished.", bundle: .appLanguage)
        }
        if let sessionOwner {
            AudioSessionCoordinator.shared.release(sessionOwner)
        }
        releaseSessionOwnershipIfIdle()
    }

    func audioPlayerDecodeErrorDidOccur(_ player: AVAudioPlayer, error: Error?) {
        guard player === self.player else { return }
        let sessionOwner = playbackSessionOwner
        playbackSessionOwner = nil
        self.player = nil
        playingURL = nil
        playbackErrorMessage = AudioCaptureError.previewFailed(
            error?.localizedDescription ?? String(localized: "The player could not decode this file.", bundle: .appLanguage)
        ).localizedDescription
        if let sessionOwner {
            AudioSessionCoordinator.shared.release(sessionOwner)
        }
        releaseSessionOwnershipIfIdle()
    }

    fileprivate func stopForExclusiveAudioHandoff() {
        handleAudioSessionLoss(
            message: String(localized: "Audio stopped because another SwiftMandarin window started using audio.", bundle: .appLanguage)
        )
    }

    fileprivate func handleAudioSessionLoss(message: String) {
        if isRecording {
            do {
                completedRecordingURL = try stopRecording()
            } catch {
                discardActiveRecording()
                playbackErrorMessage = error.localizedDescription
            }
        } else {
            discardActiveRecording()
        }
        stopPlayback()
        if playbackErrorMessage == nil {
            playbackErrorMessage = message
        }
    }

    private func requestMicrophonePermissionIfNeeded() async -> Bool {
        switch AVAudioApplication.shared.recordPermission {
        case .granted:
            return true
        case .denied:
            return false
        case .undetermined:
            return await withCheckedContinuation { continuation in
                AVAudioApplication.requestRecordPermission { granted in
                    continuation.resume(returning: granted)
                }
            }
        @unknown default:
            return false
        }
    }

    private func releaseSessionOwnershipIfIdle() {
        guard !hasActiveAudio else { return }
        SourceAudioActivityCoordinator.shared.release(self)
    }
}

