516	    private func toggleRecording() {
517	        errorMessage = nil
518	        statusMessage = nil
519	
520	        if captureService.isRecording {
521	            cancelRecordingLimit()
522	            do {
523	                let recordedURL = try captureService.stopRecording()
524	                prepareRecording(at: recordedURL)
525	            } catch {
526	                errorMessage = error.localizedDescription
527	            }
528	        } else {
529	            cancelPreparation()
530	            let requestID = UUID()
531	            preparationID = requestID
532	            preparationTask = Task {
533	                do {
534	                    try await captureService.startRecording()
535	                    try Task.checkCancellation()
536	                    guard preparationID == requestID else {
537	                        captureService.discardActiveRecording()
538	                        return
539	                    }
540	                    scheduleRecordingLimit()
541	                } catch is CancellationError {
542	                    // Leaving the pane while a permission prompt is open must
543	                    // not start a hidden recording after the prompt resolves.
544	                } catch {
545	                    if preparationID == requestID {
546	                        errorMessage = error.localizedDescription
547	                    }
548	                }
549	                finishPreparation(requestID)
550	            }
551	        }
552	    }
