554	    private func prepareRecording(at url: URL) {
555	        cancelPreparation()
556	        let requestID = UUID()
557	        preparationID = requestID
558	        isPreparingFile = true
559	        preparationTask = Task {
560	            do {
561	                let prepared = try await AudioInputFileStore.prepareRecording(at: url)
562	                guard !Task.isCancelled, preparationID == requestID else {
563	                    AudioInputFileStore.remove(prepared.url)
564	                    return
565	                }
566	                replaceSelection(with: prepared)
567	                statusMessage = String(localized: "Recording ready for transcription.", bundle: .appLanguage)
568	                statusKind = .success
569	            } catch is CancellationError {
570	                AudioInputFileStore.remove(url)
571	            } catch {
572	                if preparationID == requestID {
573	                    errorMessage = error.localizedDescription
574	                }
575	            }
576	            finishPreparation(requestID)
577	        }
578	    }
579	
580	    private func handleImportResult(_ result: Result<[URL], Error>) {
581	        guard case .success(let urls) = result, let sourceURL = urls.first else {
582	            if case .failure(let error) = result {
583	                errorMessage = error.localizedDescription
584	            }
585	            return
586	        }
587	
588	        errorMessage = nil
589	        statusMessage = nil
590	        cancelPreparation()
591	        let requestID = UUID()
592	        preparationID = requestID
593	        isPreparingFile = true
594	        preparationTask = Task {
595	            do {
596	                let prepared = try await AudioInputFileStore.importAudio(from: sourceURL)
597	                guard !Task.isCancelled, preparationID == requestID else {
598	                    AudioInputFileStore.remove(prepared.url)
599	                    return
600	                }
601	                replaceSelection(with: prepared)
602	                statusMessage = String(localized: "Audio file ready for transcription.", bundle: .appLanguage)
603	                statusKind = .success
604	            } catch is CancellationError {
605	                // Picker dismissal or replacement is not an error.
606	            } catch {
607	                if preparationID == requestID {
608	                    errorMessage = error.localizedDescription
609	                }
610	            }
611	            finishPreparation(requestID)
612	        }
613	    }
