648	    private func begin(_ action: MultimodalAudioAction) {
649	        guard let selectedAudio else { return }
650	
651	        cancelOperation(showStatus: false)
652	        captureService.stopPlayback()
653	        errorMessage = nil
654	        statusMessage = nil
655	        offerAIFallback = false
656	        operation = action == .transcribeToEditor ? .transcribing : .translating
657	        let requestID = UUID()
658	        operationID = requestID
659	        let engine = aiSettings.transcriptionEngine
660	
661	        operationTask = Task {
662	            do {
663	                let transcript = try await transcriptionService.transcribe(
664	                    audioURL: selectedAudio.url,
665	                    language: recognitionLanguage,
666	                    engine: engine
667	                )
668	                try Task.checkCancellation()
669	                guard operationID == requestID else { return }
670	                try await onResult(transcript, recognitionLanguage, action)
671	                try Task.checkCancellation()
672	                guard operationID == requestID else { return }
673	                statusMessage = action == .transcribeToEditor
674	                    ? String(localized: "Transcript added to the editor.", bundle: .appLanguage)
675	                    : String(localized: "Translation complete.", bundle: .appLanguage)
676	                statusKind = .success
677	            } catch is CancellationError {
678	                if operationID == requestID {
679	                    statusMessage = String(localized: "Cancelled.", bundle: .appLanguage)
680	                    statusKind = .neutral
681	                }
682	            } catch {
683	                if operationID == requestID {
684	                    errorMessage = error.localizedDescription
685	                    // Apple Speech has no model for this language on a lot of
686	                    // devices. Offer the switch rather than leaving a dead end.
687	                    offerAIFallback = engine == .appleSpeech
688	                        && aiSettings.isAITranscriptionAvailable
689	                }
690	            }
691	            if operationID == requestID {
692	                operation = nil
693	                operationTask = nil
694	                operationID = nil
695	            }
696	        }
697	    }
