718	    private func scheduleRecordingLimit() {
719	        cancelRecordingLimit()
720	        let requestID = UUID()
721	        recordingLimitID = requestID
722	        recordingLimitTask = Task {
723	            do {
724	                try await Task.sleep(for: .seconds(AudioInputFileStore.maximumDurationSeconds))
725	                try Task.checkCancellation()
726	                guard recordingLimitID == requestID, captureService.isRecording else { return }
727	                let recordedURL = try captureService.stopRecording()
728	                if recordingLimitID == requestID {
729	                    recordingLimitTask = nil
730	                    recordingLimitID = nil
731	                }
732	                prepareRecording(at: recordedURL)
733	            } catch is CancellationError {
734	                // Manual stop or leaving the pane cancels the deadline.
735	            } catch {
736	                if recordingLimitID == requestID {
737	                    errorMessage = error.localizedDescription
738	                }
739	            }
740	            if recordingLimitID == requestID {
741	                recordingLimitTask = nil
742	                recordingLimitID = nil
743	            }
744	        }
745	    }
