769	    private func metadataDescription(for audio: PreparedAudioFile) -> String {
770	        var components = [ByteCountFormatter.string(fromByteCount: audio.byteCount, countStyle: .file)]
771	        if let duration = audio.duration {
772	            components.insert(formatDuration(duration), at: 0)
773	        }
774	        components.append(
775	            audio.source == .recording
776	                ? String(localized: "Recording", bundle: .appLanguage)
777	                : String(localized: "Imported file", bundle: .appLanguage)
778	        )
779	        return components.joined(separator: " · ")
780	    }
781	
782	    private func formatDuration(_ duration: TimeInterval) -> String {
783	        let totalSeconds = max(0, Int(duration.rounded()))
784	        return String(format: "%d:%02d", totalSeconds / 60, totalSeconds % 60)
785	    }
