196	    /// Transcribe through the configured AI provider's speech-to-text endpoint.
197	    private func transcribeWithAI(
198	        audioURL: URL,
199	        language: SpeechRecognitionLanguage
200	    ) async throws -> String {
201	        let settings = AIModelSettings.shared
202	        guard let provider = settings.transcriptionProvider() else {
203	            throw AudioTranscriptionError.noTranscriptionProvider
204	        }
205	        try Task.checkCancellation()
206	        let transcript = try await CloudAIService.shared.transcribeAudio(
207	            provider: provider,
208	            model: settings.transcriptionModel(for: provider),
209	            audioURL: audioURL,
210	            languageCode: language.transcriptionLanguageCode
211	        )
212	        // A provider that heard nothing returns an empty or whitespace body;
